import React, { useState, useCallback, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ChatWindow from './components/ChatWindow';
import InputBar from './components/InputBar';
import LoginModal from './components/LoginModal';
import CitySelector from './components/CitySelector';
import { Message, ChatHistory } from './types';
import { getGeminiResponse } from './services/geminiService';
import { 
  Moon, 
  Sun, 
  Cloud, 
  X, 
  Volume2, 
  Mic, 
  RefreshCw, 
  ChevronDown, 
  CloudRain, 
  CloudLightning 
} from 'lucide-react';
import { SUBTITLE } from './constants';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';

const encode = (bytes: Uint8Array) => {
  let binary = '';
  for (let i = 0; i < bytes.byteLength; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
};

const decode = (base64: string) => {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
};

const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number) => {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
  }
  return buffer;
};

const App: React.FC = () => {
  const [selectedCity, setSelectedCity] = useState('Madurai');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isCitySelectorOpen, setIsCitySelectorOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([]);
  const [history, setHistory] = useState<ChatHistory[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [isLoginOpen, setIsLoginOpen] = useState(false);

  // Weather State
  const [weather, setWeather] = useState({ temp: '--', condition: 'Loading...' });
  const [isWeatherRefreshing, setIsWeatherRefreshing] = useState(false);

  // Live Mode State
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [liveTranscription, setLiveTranscription] = useState('');
  const liveSessionRef = useRef<any>(null);
  const liveAudioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const liveNextStartTimeRef = useRef(0);
  const liveSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Handle Dark Mode
  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  const handleRefreshWeather = useCallback(async (city: string) => {
    if (isWeatherRefreshing) return;
    setIsWeatherRefreshing(true);
    try {
      const prompt = `What is the current temperature and short sky condition in ${city}, Tamil Nadu right now? Reply ONLY with JSON: {"temp": "number", "condition": "brief"}`;
      const response = await getGeminiResponse(prompt, [], city);
      try {
        const cleaned = response.replace(/```json|```/g, '').trim();
        const data = JSON.parse(cleaned);
        if (data.temp && data.condition) {
          setWeather({ temp: data.temp.toString().replace('°C', ''), condition: data.condition });
        }
      } catch {
        const tempMatch = response.match(/(\d+)/);
        if (tempMatch) {
          setWeather(prev => ({ ...prev, temp: tempMatch[1] }));
        }
      }
    } catch (e) {
      console.error("Weather refresh failed", e);
    } finally {
      setIsWeatherRefreshing(false);
    }
  }, [isWeatherRefreshing]);

  // Initial weather fetch or whenever city changes
  useEffect(() => {
    handleRefreshWeather(selectedCity);
  }, [selectedCity]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  const handleSendMessage = useCallback(async (text: string, files?: { data: string, mimeType: string }[]) => {
    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setIsLoading(true);

    const chatHistoryForAPI = messages.map(m => ({
      role: m.role === 'assistant' ? 'model' as const : 'user' as const,
      parts: [{ text: m.content }]
    }));

    const responseText = await getGeminiResponse(text, chatHistoryForAPI, selectedCity);

    const assistantMsg: Message = {
      id: (Date.now() + 1).toString(),
      role: 'assistant',
      content: responseText,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, assistantMsg]);
    setIsLoading(false);

    if (messages.length === 0) {
      setHistory(prev => [{
        id: Date.now().toString(),
        title: text.length > 25 ? text.substring(0, 25) + '...' : text,
        lastUpdated: new Date()
      }, ...prev]);
    }
  }, [messages, selectedCity]);

  const handleUtilityAction = (action: 'news' | 'analytics' | 'promote' | 'about') => {
    setIsSidebarOpen(false);
    switch (action) {
      case 'news':
        handleSendMessage(`What is the latest news and trending topics in ${selectedCity} right now?`);
        break;
      case 'analytics':
        handleSendMessage(`Show me some interesting analytics and facts about ${selectedCity} (population, top industries, tourism stats).`);
        break;
      case 'promote':
        const promoteMsg: Message = {
          id: Date.now().toString(),
          role: 'assistant',
          content: `Let's promote ${selectedCity}! 🏛️✨\n\nYou can share this app with your friends to help them explore this beautiful place. Sharing link copied to clipboard!`,
          timestamp: new Date()
        };
        setMessages(prev => [...prev, promoteMsg]);
        navigator.clipboard.writeText(`https://${selectedCity.toLowerCase()}-info.ai`);
        break;
      case 'about':
        handleSendMessage(`Tell me more about yourself, ${selectedCity} Info AI, and how you can help me explore ${selectedCity}.`);
        break;
    }
  };

  const stopLiveMode = useCallback(() => {
    if (liveSessionRef.current) liveSessionRef.current.close();
    liveSessionRef.current = null;
    liveSourcesRef.current.forEach(s => s.stop());
    liveSourcesRef.current.clear();
    if (liveAudioContextRef.current) {
      liveAudioContextRef.current.input.close();
      liveAudioContextRef.current.output.close();
    }
    setIsLiveActive(false);
    setLiveTranscription('');
  }, []);

  const startLiveMode = useCallback(async () => {
    try {
      setIsLiveActive(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      liveAudioContextRef.current = { input: inputCtx, output: outputCtx };

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              sessionPromise.then(s => s.sendRealtimeInput({ media: { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (m: LiveServerMessage) => {
            const audioData = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              liveNextStartTimeRef.current = Math.max(liveNextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), outputCtx, 24000, 1);
              const source = outputCtx.createBufferSource();
              source.buffer = buffer;
              source.connect(outputCtx.destination);
              source.onended = () => liveSourcesRef.current.delete(source);
              source.start(liveNextStartTimeRef.current);
              liveNextStartTimeRef.current += buffer.duration;
              liveSourcesRef.current.add(source);
            }
            if (m.serverContent?.outputTranscription) setLiveTranscription(prev => prev + m.serverContent?.outputTranscription?.text);
            if (m.serverContent?.turnComplete) setLiveTranscription('');
          },
          onclose: () => stopLiveMode(),
          onerror: () => stopLiveMode()
        },
        config: {
          responseModalities: [Modality.AUDIO],
          systemInstruction: `You are ${selectedCity} Info AI in a live voice conversation. Be friendly, keep answers very brief and natural.`,
          outputAudioTranscription: {}
        }
      });
      liveSessionRef.current = await sessionPromise;
    } catch (e) {
      console.error(e);
      stopLiveMode();
    }
  }, [stopLiveMode, selectedCity]);

  const WeatherIcon = () => {
    const cond = weather.condition.toLowerCase();
    if (cond.includes('rain')) return <CloudRain size={28} className="text-blue-500 transition-colors" />;
    if (cond.includes('storm')) return <CloudLightning size={28} className="text-purple-500 transition-colors" />;
    if (cond.includes('sun') || cond.includes('clear')) return <Sun size={28} className="text-orange-400 transition-colors" />;
    return <Cloud size={28} className="text-slate-400 transition-colors" />;
  };

  const handleCitySelect = (city: string) => {
    setSelectedCity(city);
    setMessages([]); // Clear chat when switching city for context safety
  };

  return (
    <div className="flex h-screen bg-[#fffaf5] dark:bg-[#0c0600] overflow-hidden text-elegant-light dark:text-elegant-dark checker-bg relative transition-all duration-700 ease-in-out">
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/5 dark:bg-black/40 backdrop-blur-[1px] z-40" onClick={() => setIsSidebarOpen(false)} />
      )}

      <Sidebar 
        isOpen={isSidebarOpen} 
        onClose={() => setIsSidebarOpen(false)}
        history={history}
        onNewChat={() => { setMessages([]); setIsSidebarOpen(false); }}
        onSelectHistory={() => setIsSidebarOpen(false)}
        onUtilityAction={handleUtilityAction}
        onLogin={() => { setIsLoginOpen(true); setIsSidebarOpen(false); }}
      />

      <div className="flex-1 flex flex-col min-w-0 relative">
        <header className="h-24 flex items-center px-6 md:px-10 relative bg-white/30 dark:bg-black/20 backdrop-blur-md border-b border-orange-100/30">
          <div className="flex items-center absolute left-6 md:left-10">
            <button 
              onClick={(e) => { e.stopPropagation(); setIsSidebarOpen(!isSidebarOpen); }}
              className="w-12 h-12 flex items-center justify-center transition-all hover:scale-105 active:scale-95 focus:outline-none"
            >
              {/* Concentric Circle Logo matching the user's reference image */}
              <div className="relative w-10 h-10 flex items-center justify-center">
                {/* Outer ring */}
                <div className="absolute inset-0 rounded-full border-[3px] border-orange-500" />
                {/* Inner ring */}
                <div className="absolute inset-[6px] rounded-full border-[3px] border-orange-500" />
                {/* Center dot */}
                <div className="w-2.5 h-2.5 rounded-full bg-orange-500" />
              </div>
            </button>
          </div>

          <div className="flex flex-col items-center justify-center w-full">
            <button 
              onClick={() => setIsCitySelectorOpen(true)}
              className="group flex flex-col items-center justify-center transition-all hover:opacity-80 active:scale-95 px-4 py-1 rounded-2xl hover:bg-orange-50/50 dark:hover:bg-orange-900/10"
            >
              <div className="flex items-center gap-1.5">
                <h1 className="text-[26px] md:text-[28px] font-bold text-[#f97316] tracking-tight">{selectedCity} Info AI</h1>
                <ChevronDown size={24} className="text-[#f97316] mt-1 transition-transform group-hover:translate-y-0.5" />
              </div>
              <p className="text-[12px] md:text-[13px] text-slate-500 font-medium tracking-wide">{SUBTITLE}</p>
            </button>
          </div>

          <div className="absolute right-6 md:right-10 flex items-center gap-4 md:gap-6">
             <button 
               onClick={() => handleRefreshWeather(selectedCity)}
               className={`hidden sm:flex items-center gap-2.5 transition-all p-2 rounded-xl hover:bg-white/50 dark:hover:bg-white/5 ${isWeatherRefreshing ? 'opacity-70' : ''}`}
               title="Refresh weather"
             >
                {isWeatherRefreshing ? (
                  <RefreshCw size={24} className="text-slate-500 animate-spin" />
                ) : (
                  <WeatherIcon />
                )}
                <div className="flex flex-col items-start leading-none">
                  <span className="text-[17px] font-semibold text-slate-700 dark:text-slate-300">{weather.temp}°C</span>
                </div>
             </button>
             <button 
               onClick={toggleTheme}
               className="p-2 text-slate-700 dark:text-orange-200 transition-all hover:scale-110 rounded-xl hover:bg-white/50 dark:hover:bg-white/5"
             >
               {theme === 'light' ? <Moon size={28} /> : <Sun size={28} />}
             </button>
          </div>
        </header>

        <main className="flex-1 flex flex-col relative overflow-hidden" onClick={() => isSidebarOpen && setIsSidebarOpen(false)}>
          <ChatWindow messages={messages} onSuggestionClick={handleSendMessage} isLoading={isLoading} />
          <div className="w-full">
            <InputBar onSendMessage={handleSendMessage} onStartLive={startLiveMode} isLoading={isLoading} />
          </div>
        </main>

        {isLiveActive && (
          <div className="fixed inset-0 z-[60] bg-[#f97316]/95 backdrop-blur-md flex flex-col items-center justify-center text-white p-8 animate-in fade-in zoom-in duration-300">
            <button onClick={stopLiveMode} className="absolute top-10 right-10 p-4 bg-white/10 hover:bg-white/20 rounded-full transition-all">
              <X size={36} />
            </button>
            <div className="w-56 h-56 bg-white/10 rounded-full flex items-center justify-center relative mb-16">
              <div className="absolute inset-0 rounded-full border-4 border-white/20 animate-ping" />
              <div className="absolute inset-4 rounded-full border-4 border-white/30 animate-ping delay-150" />
              <div className="w-36 h-36 bg-white rounded-full flex items-center justify-center shadow-2xl">
                <Volume2 size={72} className="text-[#f97316] animate-pulse" />
              </div>
            </div>
            <h2 className="text-4xl font-bold mb-6 tracking-tight">{selectedCity} Live AI</h2>
            <p className="text-orange-50 text-xl text-center max-w-lg font-medium leading-relaxed italic opacity-90 px-4">
              {liveTranscription || `Listening... Talk to me about ${selectedCity}.`}
            </p>
            <div className="mt-20 px-6 py-3 bg-white/10 rounded-full border border-white/20 flex items-center gap-3">
              <Mic size={20} className="text-green-300 animate-pulse" />
              <span className="text-xs font-bold tracking-[0.2em] uppercase">Session Active</span>
            </div>
          </div>
        )}

        <LoginModal isOpen={isLoginOpen} onClose={() => setIsLoginOpen(false)} />
        <CitySelector 
          isOpen={isCitySelectorOpen} 
          onClose={() => setIsCitySelectorOpen(false)} 
          onSelect={handleCitySelect}
          currentCity={selectedCity}
        />
      </div>
    </div>
  );
};

export default App;

