import React, { useState, useRef, useEffect, useCallback } from 'react';
import { 
  Paperclip, 
  Mic, 
  Send,
  Image as ImageIcon,
  Loader2
} from 'lucide-react';

interface InputBarProps {
  onSendMessage: (message: string, files?: { data: string, mimeType: string }[]) => void;
  onStartLive: () => void;
  isLoading: boolean;
}

const InputBar: React.FC<InputBarProps> = ({ onSendMessage, onStartLive, isLoading }) => {
  const [input, setInput] = useState('');
  const [isListening, setIsListening] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const longPressTimer = useRef<number | null>(null);

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (input.trim() && !isLoading) {
      onSendMessage(input.trim());
      setInput('');
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 120)}px`;
    }
  }, [input]);

  const startVoiceTyping = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Speech recognition is not supported in this browser.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-IN';
    recognition.interimResults = false;

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onerror = () => setIsListening(false);

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(prev => prev + (prev ? ' ' : '') + transcript);
    };

    recognition.start();
  }, []);

  const handleMicMouseDown = () => {
    longPressTimer.current = window.setTimeout(() => {
      onStartLive();
      longPressTimer.current = null;
    }, 600);
  };

  const handleMicMouseUp = () => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
      startVoiceTyping();
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>, label: string) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = () => {
      const base64 = (reader.result as string).split(',')[1];
      onSendMessage(`I've shared a ${label} with you.`, [{ data: base64, mimeType: file.type }]);
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  return (
    <div className="max-w-5xl mx-auto w-full px-4 pb-8 flex flex-col items-center">
      <input type="file" ref={fileInputRef} className="hidden" onChange={(e) => handleFileChange(e, 'file')} />
      <input type="file" ref={imageInputRef} accept="image/*" className="hidden" onChange={(e) => handleFileChange(e, 'image')} />

      <div className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl rounded-[28px] shadow-2xl border border-slate-200/50 dark:border-slate-800 p-2 flex items-center gap-1 w-full max-w-4xl transition-all focus-within:ring-4 focus-within:ring-orange-500/5">
        <div className="flex items-center pl-2">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="p-2.5 text-slate-400 hover:text-orange-500 hover:bg-orange-50 dark:hover:bg-orange-950/20 rounded-full transition-all"
            title="Attach File"
          >
            <Paperclip size={20} strokeWidth={2} />
          </button>
          <button 
            onClick={() => imageInputRef.current?.click()}
            className="p-2.5 text-slate-400 hover:text-orange-500 hover:bg-orange-50 dark:hover:bg-orange-950/20 rounded-full transition-all"
            title="Share Image"
          >
            <ImageIcon size={20} strokeWidth={2} />
          </button>
          <button 
            onMouseDown={handleMicMouseDown}
            onMouseUp={handleMicMouseUp}
            onMouseLeave={() => longPressTimer.current && clearTimeout(longPressTimer.current)}
            className={`p-2.5 transition-all relative rounded-full ${isListening ? 'text-orange-600 bg-orange-100' : 'text-slate-400 hover:text-orange-500 hover:bg-orange-50 dark:hover:bg-orange-950/20'}`}
            title="Voice Typing (Hold for Live Mode)"
          >
            <Mic size={20} strokeWidth={2} />
            {isListening && (
              <span className="absolute inset-0 rounded-full bg-orange-500 animate-ping opacity-30" />
            )}
          </button>
        </div>

        <div className="flex-1 flex items-center gap-3 ml-2">
          <div className="hidden sm:flex text-[11px] font-black text-white bg-orange-500/90 dark:bg-orange-600/90 px-2 py-1 rounded-md uppercase tracking-widest whitespace-nowrap select-none shadow-sm shadow-orange-200 dark:shadow-none">
            தமிழ்
          </div>
          <textarea
            ref={textareaRef}
            rows={1}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Type in English or தமிழ்... ✨"
            className="w-full bg-transparent py-3 resize-none outline-none text-[16px] text-slate-800 dark:text-slate-100 placeholder:text-slate-400 font-medium leading-normal"
          />
        </div>

        <button
          onClick={() => handleSubmit()}
          disabled={!input.trim() || isLoading}
          className={`mr-1 w-12 h-12 rounded-full transition-all flex items-center justify-center ${
            input.trim() && !isLoading 
            ? 'bg-[#f97316] hover:bg-[#ea580c] text-white shadow-lg shadow-orange-200 dark:shadow-none hover:scale-105 active:scale-95' 
            : 'bg-slate-100 dark:bg-slate-800 text-slate-300 dark:text-slate-600 cursor-not-allowed'
          }`}
        >
          {isLoading ? <Loader2 size={24} className="animate-spin" /> : <Send size={20} className="fill-current stroke-[2.5]" />}
        </button>
      </div>

      <p className="mt-4 text-[11px] font-bold text-slate-400/70 tracking-widest uppercase">
        Madurai Info AI · Local Intelligence · © 2024
      </p>
    </div>
  );
};

