const FormattedContent: React.FC<{ content: string; role: 'user' | 'assistant' }> = ({ content, role }) => {
  if (role === 'user') return <>{content}</>;

  // Split content by lines to identify structure
  const lines = content.split('\n');

  return (
    <div className="space-y-4">
      {lines.map((line, i) => {
        const trimmed = line.trim();
        if (!trimmed) return <div key={i} className="h-2" />;

        // Header Check (starts with # or just all caps/bold-like)
        if (trimmed.startsWith('**') && trimmed.endsWith('**')) {
          return (
            <h4 key={i} className="text-orange-700 dark:text-orange-400 font-black text-lg mt-4 mb-2 flex items-center gap-2">
              <span className="w-1.5 h-4 bg-orange-500 rounded-full block"></span>
              {trimmed.replace(/\*\*/g, '')}
            </h4>
          );
        }

        // List Item Check
        if (trimmed.startsWith('-') || trimmed.startsWith('*') || /^\d+\./.test(trimmed)) {
          return (
            <div key={i} className="flex gap-3 pl-2 py-1 items-start group">
              <span className="text-orange-500 font-bold mt-0.5 group-hover:scale-125 transition-transform">✦</span>
              <span className="text-slate-700 dark:text-slate-200 leading-relaxed">
                {trimmed.replace(/^[-*]\s*|^\d+\.\s*/, '')}
              </span>
            </div>
          );
        }

        return (
          <p key={i} className="text-slate-700 dark:text-slate-200 leading-[1.8] tracking-tight font-normal">
            {line}
          </p>
        );
      })}
    </div>
  );
};

