const FormattedAssistantContent: React.FC<{ content: string }> = ({ content }) => {
  const lines = content.split('\n');
  return (
    <div className="space-y-4">
      {lines.map((line, i) => {
        const trimmed = line.trim();
        if (!trimmed) return <div key={i} className="h-1" />;

        // Header detection (Bolded lines)
        if (trimmed.startsWith('**') && trimmed.endsWith('**')) {
          const title = trimmed.replace(/\*\*/g, '');
          return (
            <div key={i} className="mt-6 mb-2 flex items-center gap-2 bg-orange-50/50 dark:bg-orange-900/10 p-2 rounded-lg border-l-4 border-orange-500">
              <span className="text-lg font-black text-orange-700 dark:text-orange-400 tracking-tight leading-none uppercase text-[13px]">
                {title}
              </span>
            </div>
          );
        }

        // List item detection
        if (trimmed.startsWith('-') || trimmed.startsWith('*') || /^\d+\./.test(trimmed)) {
          return (
            <div key={i} className="flex gap-3 pl-1 items-start group">
              <span className="text-orange-500 font-bold mt-1 scale-125 select-none">✦</span>
              <span className="text-slate-700 dark:text-slate-200 leading-relaxed font-medium">
                {trimmed.replace(/^[-*]\s*|^\d+\.\s*/, '')}
              </span>
            </div>
          );
        }

        // Regular paragraph
        return (
          <p key={i} className="text-slate-700 dark:text-slate-200 leading-[1.75] font-normal tracking-tight">
            {line}
          </p>
        );
      })}
    </div>
  );
};

