  const fileInputRef = useRef<HTMLInputElement>(null);
  const longPressTimer = useRef<number | null>(null);

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (input.trim() && !isLoading) {
      onSendMessage(input.trim());
      setInput('');
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 120)}px`;
    }
  }, [input]);

  const startVoiceTyping = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Speech recognition is not supported in this browser.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-IN';
    recognition.interimResults = false;

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onerror = () => setIsListening(false);

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(prev => prev + (prev ? ' ' : '') + transcript);
    };

    recognition.start();
  }, []);

  const handleMicMouseDown = () => {
    longPressTimer.current = window.setTimeout(() => {
      onStartLive();
      longPressTimer.current = null;
    }, 600);
  };

  const handleMicMouseUp = () => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
      startVoiceTyping();
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>, label: string) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = () => {
      const base64 = (reader.result as string).split(',')[1];
      onSendMessage(`I've shared a ${label} with you.`, [{ data: base64, mimeType: file.type }]);
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  return (
    <div className="max-w-5xl mx-auto w-full px-4 pb-10 flex flex-col items-center">
      <input type="file" ref={fileInputRef} className="hidden" onChange={(e) => handleFileChange(e, 'file')} />

      <div className="bg-white dark:bg-slate-900 rounded-full shadow-[0_2px_15px_rgba(0,0,0,0.05)] border border-slate-100 dark:border-slate-800 p-2.5 flex items-center gap-2 w-full max-w-4xl">
        <div className="flex items-center pl-3 gap-1">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="p-2 text-slate-400 hover:text-orange-500 transition-colors"
            title="Attach File"
          >
            <Paperclip size={22} strokeWidth={1.5} />
          </button>
          <button 
            onClick={onOpenImageGen}
            className="p-2 text-slate-400 hover:text-orange-500 transition-colors group relative"
            title="AI Image Generator"
          >
            <Sparkles size={22} strokeWidth={1.5} className="group-hover:rotate-12 transition-transform" />
            <span className="absolute -top-1 -right-1 w-2 h-2 bg-orange-500 rounded-full animate-pulse" />
          </button>
          <button 
            onMouseDown={handleMicMouseDown}
            onMouseUp={handleMicMouseUp}
            onMouseLeave={() => longPressTimer.current && clearTimeout(longPressTimer.current)}
            className={`p-2 transition-all relative ${isListening ? 'text-orange-500' : 'text-slate-400 hover:text-orange-500'}`}
            title="Voice Typing (Hold for Live AI)"
          >
            <Mic size={22} strokeWidth={1.5} />
            {isListening && (
              <span className="absolute inset-0 rounded-full bg-orange-100 dark:bg-orange-950/30 animate-ping opacity-50" />
            )}
          </button>
        </div>

        <div className="flex-1 flex items-center gap-4 ml-2">
          <div className="text-[13px] font-bold text-slate-500 bg-slate-100 dark:bg-slate-800 px-3 py-1.5 rounded-lg uppercase tracking-tight whitespace-nowrap select-none">
            தமிழ்
          </div>
          <textarea
            ref={textareaRef}
            rows={1}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Ask in English or தமிழ்..."
            className="w-full bg-transparent py-2 resize-none outline-none text-base text-slate-700 dark:text-slate-200 placeholder:text-slate-400 font-medium"
          />
        </div>

        <button
          onClick={() => handleSubmit()}
          disabled={!input.trim() || isLoading}
          className={`mr-1 w-11 h-11 rounded-full transition-all flex items-center justify-center ${
            input.trim() && !isLoading 
            ? 'bg-[#f97316] hover:bg-[#ea580c] text-white shadow-md' 
            : 'bg-[#ffedd5] text-[#fdba74] cursor-not-allowed'
          }`}
        >
          {isLoading ? <Loader2 size={24} className="animate-spin" /> : <Send size={20} className="fill-current stroke-[2.5]" />}
        </button>
      </div>
    </div>
  );
};

