interface ImageGenModalProps {
  isOpen: boolean;
  onClose: () => void;
  city: string;
}

const ImageGenModal: React.FC<ImageGenModalProps> = ({ isOpen, onClose, city }) => {
  const [prompt, setPrompt] = useState(`A beautiful cinematic painting of the Madurai Meenakshi Temple at sunset, golden hour, intricate carvings, traditional Tamil architecture, 8k resolution.`);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  if (!isOpen) return null;

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [{ text: `${prompt}. Make it highly detailed, aesthetic and professional.` }],
        },
        config: {
          imageConfig: {
            aspectRatio: "1:1"
          }
        }
      });

      let foundImage = false;
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          const base64EncodeString = part.inlineData.data;
          setGeneratedImage(`data:image/png;base64,${base64EncodeString}`);
          foundImage = true;
          break;
        }
      }

      if (!foundImage) {
        throw new Error("No image data found in response.");
      }
    } catch (e) {
      console.error("Image generation failed", e);
      setError("Failed to generate image. Please try a different description or try again later.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleDownload = () => {
    if (!generatedImage) return;
    const link = document.createElement('a');
    link.href = generatedImage;
    link.download = `ai-art-${city.toLowerCase()}-${Date.now()}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
