        {/* Close Button */}
        <button 
          onClick={onClose}
          className="absolute top-6 right-6 z-20 p-2.5 bg-white/80 dark:bg-black/80 text-slate-600 dark:text-slate-400 hover:text-orange-500 rounded-full transition-all shadow-lg hover:scale-110"
        >
          <X size={20} />
        </button>

        {/* Left Side: Preview */}
        <div className="w-full md:w-1/2 h-[350px] md:h-auto bg-slate-100 dark:bg-slate-900 flex items-center justify-center relative group">
          {generatedImage ? (
            <>
              <img 
                src={generatedImage} 
                alt="AI Generated Art" 
                className="w-full h-full object-cover animate-in fade-in zoom-in duration-700"
              />
              <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-all flex items-center justify-center opacity-0 group-hover:opacity-100">
                <button 
                  onClick={handleDownload}
                  className="bg-white text-orange-500 p-4 rounded-full shadow-2xl hover:scale-110 active:scale-95 transition-all flex items-center gap-2 font-bold"
                >
                  <Download size={24} />
                  Download Art
                </button>
              </div>
            </>
          ) : (
            <div className="flex flex-col items-center gap-6 p-12 text-center">
              <div className="w-24 h-24 bg-orange-100 dark:bg-orange-900/20 rounded-full flex items-center justify-center">
                <Sparkles size={48} className="text-orange-500 animate-pulse" />
              </div>
              <div>
                <h3 className="text-xl font-bold text-slate-800 dark:text-slate-200 mb-2">Ready to Visualize?</h3>
                <p className="text-slate-500 dark:text-slate-400 text-sm font-medium">Your generated city art will appear here. Be specific for better results!</p>
              </div>
            </div>
          )}

          {isGenerating && (
            <div className="absolute inset-0 bg-white/60 dark:bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center z-10 animate-in fade-in">
              <div className="relative">
                <div className="w-16 h-16 border-4 border-orange-500/20 border-t-orange-500 rounded-full animate-spin"></div>
                <Wand2 size={24} className="text-orange-500 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-bounce" />
              </div>
              <p className="mt-4 text-orange-600 dark:text-orange-400 font-black text-sm tracking-widest uppercase animate-pulse">Generating your vision...</p>
            </div>
