        </div>

        {/* Right Side: Controls */}
        <div className="w-full md:w-1/2 p-8 md:p-12 flex flex-col gap-6">
          <div>
            <div className="flex items-center gap-2 mb-2">
              <Sparkles size={18} className="text-orange-500" />
              <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 tracking-tight">AI Art Studio</h2>
            </div>
            <p className="text-slate-500 dark:text-slate-400 text-sm font-medium">Create unique visuals of {city} and beyond using advanced AI.</p>
          </div>

          <div className="flex flex-col gap-2">
            <label className="text-xs font-black text-slate-400 uppercase tracking-[0.2em] ml-1">Describe your vision</label>
            <textarea 
              value={prompt}
