              )}
            </button>

            {generatedImage && !isGenerating && (
              <button 
                onClick={() => handleGenerate()}
                className="w-16 h-16 bg-white dark:bg-slate-900 border border-orange-100 dark:border-orange-900 text-slate-600 dark:text-slate-400 rounded-3xl flex items-center justify-center hover:bg-orange-50 dark:hover:bg-orange-900/10 transition-all group shadow-sm"
                title="Regenerate"
              >
                <RefreshCw size={24} className="group-hover:rotate-180 transition-transform duration-700" />
