// Function to handle inline bolding (**text**)
const renderInlineText = (text: string) => {
  const parts = text.split(/(\*\*.*?\*\*)/g);
  return parts.map((part, i) => {
    if (part.startsWith('**') && part.endsWith('**')) {
      return <strong key={i} className="font-extrabold text-slate-900 dark:text-white">{part.slice(2, -2)}</strong>;
    }
    return part;
  });
};

const FormattedAssistantContent: React.FC<{ content: string }> = ({ content }) => {
  const lines = content.split('\n');
  return (
    <div className="space-y-4">
      {lines.map((line, i) => {
        const trimmed = line.trim();
        if (!trimmed) return <div key={i} className="h-1" />;

        // Header detection: matches numbered items (1. Title) or bold headers (**Title**)
        const headerMatch = trimmed.match(/^(\d+\.\s*|(?:\*\*))(.+?)(?:\*\*|)$/);

        if (headerMatch || (trimmed.startsWith('**') && trimmed.endsWith('**'))) {
          const titleText = trimmed.replace(/\*\*/g, '').toUpperCase();
          return (
            <div key={i} className="mt-8 mb-5 flex items-center bg-[#FFF8F0] dark:bg-orange-900/10 rounded-r-2xl border-l-[6px] border-orange-600 shadow-sm overflow-hidden">
              <span className="px-5 py-3.5 text-xl md:text-[22px] font-black text-[#D35400] dark:text-orange-400 tracking-tight leading-tight uppercase">
                {titleText}
              </span>
            </div>
          );
        }

        // List item detection (using diamond icon from image)
        if (trimmed.startsWith('-') || trimmed.startsWith('*') || /^\d+\.\s+/.test(trimmed)) {
          const textWithoutMarker = trimmed.replace(/^[-*]\s*|^\d+\.\s+/, '');
          return (
            <div key={i} className="flex gap-3 pl-1 items-start group">
              <span className="text-orange-500 font-bold mt-1.5 scale-125 select-none shrink-0">✦</span>
              <span className="text-slate-700 dark:text-slate-200 leading-relaxed font-medium">
                {renderInlineText(textWithoutMarker)}
              </span>
            </div>
          );
        }

        // Regular paragraph
        return (
          <p key={i} className="text-slate-700 dark:text-slate-200 leading-[1.75] font-normal tracking-tight">
            {renderInlineText(line)}
          </p>
        );
      })}
    </div>
  );
};

