import React, { useState, useEffect, useCallback } from 'react';
import { ArrowLeft, Newspaper, RefreshCw, ExternalLink, Loader2 } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

interface NewsItem {
  source: string;
  title: string;
  description: string;
  url?: string;
}

interface NewsViewProps {
  onBack: () => void;
  city: string;
}

const NewsView: React.FC<NewsViewProps> = ({ onBack, city }) => {
  const [newsItems, setNewsItems] = useState<NewsItem[]>([]);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchRealtimeNews = useCallback(async () => {
    setIsRefreshing(true);
    setError(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Fetch the top 4 latest news headlines and short descriptions for ${city}, Tamil Nadu from the last 24-48 hours. 
      Format the response exactly as a JSON array of objects with keys: "source", "title", "description". 
      Only return the JSON. Use reliable sources like The Hindu, Times of India, or local news portals.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: {
          tools: [{ googleSearch: {} }],
        },
      });

      const text = response.text || "";
      // Extract JSON from potentially markdown-wrapped response
      const jsonMatch = text.match(/\[[\s\S]*\]/);
      if (jsonMatch) {
        const items = JSON.parse(jsonMatch[0]);

        // Try to match grounding chunks to URLs if available
        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
        const itemsWithUrls = items.map((item: any, index: number) => {
          // Simplistic mapping: assign URLs from search results to items if possible
          const url = groundingChunks[index]?.web?.uri || groundingChunks[0]?.web?.uri;
          return { ...item, url };
        });

        setNewsItems(itemsWithUrls);
      } else {
        throw new Error("Could not parse news data.");
      }
    } catch (e) {
      console.error("News fetch failed", e);
      setError("Failed to fetch latest news. Showing fallback updates.");
      // Fallback data if API fails
      setNewsItems([
        {
          source: 'Local Update',
          title: `${city} Infrastructure Development Update`,
          description: `New projects aimed at improving ${city}'s urban landscape and citizen services have been discussed in recent council meetings.`
        },
        {
          source: 'Culture Desk',
          title: 'Upcoming Cultural Festivities in Madurai Region',
          description: 'Local authorities are preparing for seasonal festivals with enhanced security and visitor facilities.'
        }
      ]);
    } finally {
      setIsRefreshing(false);
    }
  }, [city]);

  useEffect(() => {
    fetchRealtimeNews();
  }, [fetchRealtimeNews]);

  return (
    <div className="flex-1 flex flex-col bg-white dark:bg-[#0c0c0e] animate-in fade-in slide-in-from-right-4 duration-500">
      <header className="px-6 py-6 flex items-center justify-between border-b border-gray-100 dark:border-gray-800">
        <div className="flex items-center gap-4">
          <button 
            onClick={onBack}
            className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition-colors"
          >
            <ArrowLeft size={24} className="text-gray-600 dark:text-gray-400" />
          </button>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 flex items-center justify-center">
              <svg width="32" height="32" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
                <circle cx="50" cy="50" r="50" fill="#f97316" />
                <circle cx="50" cy="50" r="35" stroke="white" strokeWidth="6" />
                <path d="M62 38 A 15 15 0 1 0 62 62" stroke="white" strokeWidth="7" strokeLinecap="round" fill="none" />
              </svg>
            </div>
            <div>
              <h1 className="text-xl font-black text-[#f97316] leading-none">{city} Updates</h1>
              <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-wider">Live News & Videos</p>
            </div>
          </div>
        </div>

        <button 
          onClick={fetchRealtimeNews}
          disabled={isRefreshing}
          className="flex items-center gap-2 px-5 py-2.5 bg-orange-50 dark:bg-orange-900/10 text-orange-600 dark:text-orange-400 rounded-2xl font-black text-sm hover:bg-orange-100 dark:hover:bg-orange-900/20 transition-all active:scale-95 disabled:opacity-50"
        >
          {isRefreshing ? (
            <Loader2 size={18} className="animate-spin" />
          ) : (
            <RefreshCw size={18} />
          )}
          <span>Refresh News</span>
        </button>
      </header>

      <div className="flex-1 overflow-y-auto p-6 md:p-10 custom-scrollbar">
        <div className="max-w-6xl mx-auto">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-3">
              <Newspaper className="text-[#f97316]" size={28} />
              <h2 className="text-2xl font-black text-[#f97316]">Latest News</h2>
            </div>
            {isRefreshing && (
              <span className="text-xs font-bold text-orange-500 animate-pulse tracking-widest uppercase">Fetching real-time updates...</span>
            )}
          </div>

          {error && (
            <div className="mb-6 p-4 bg-orange-50 dark:bg-orange-900/10 rounded-xl text-orange-700 dark:text-orange-300 text-sm font-bold border border-orange-100 dark:border-orange-900/30">
              {error}
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {newsItems.map((news, idx) => (
              <div 
                key={idx} 
                className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-gray-100 dark:border-gray-800 shadow-sm hover:shadow-xl transition-all group flex flex-col"
              >
                <div className="flex justify-between items-start mb-3">
                  <span className="text-xs font-black text-orange-600 dark:text-orange-400 uppercase tracking-widest">
                    {news.source}
                  </span>
                  {news.url && (
                    <a 
                      href={news.url} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="text-slate-400 hover:text-orange-500 transition-colors"
                      title="Read Source"
                    >
                      <ExternalLink size={16} />
                    </a>
                  )}
                </div>
                <h3 className="text-xl font-extrabold text-slate-800 dark:text-slate-100 mb-4 leading-tight group-hover:text-orange-600 transition-colors">
                  {news.title}
                </h3>
                <p className="text-slate-500 dark:text-slate-400 text-sm leading-relaxed font-medium mb-6">
                  {news.description}
                </p>

                {news.url && (
                  <a 
                    href={news.url} 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="mt-auto inline-flex items-center gap-2 text-xs font-black text-orange-600 dark:text-orange-400 uppercase tracking-widest hover:underline decoration-2"
                  >
                    Read full article <ExternalLink size={12} />
                  </a>
                )}
              </div>
            ))}
          </div>

          {newsItems.length === 0 && !isRefreshing && (
            <div className="text-center py-20">
              <div className="w-20 h-20 bg-slate-50 dark:bg-slate-900 rounded-full flex items-center justify-center mx-auto mb-6">
                <Newspaper size={40} className="text-slate-300" />
              </div>
              <p className="text-slate-500 font-bold italic">No news updates available at the moment.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

