const NewsView: React.FC<NewsViewProps> = ({ onBack, city }) => {
  const [newsItems, setNewsItems] = useState<NewsItem[]>([]);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchRealtimeNews = useCallback(async () => {
    setIsRefreshing(true);
    setError(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Fetch the top 4 latest local news headlines and short summaries for the city of "${city}", Tamil Nadu from the last 48 hours. 
      Focus ONLY on news specifically about ${city}. 
      Format the response exactly as a JSON array of objects with keys: "source", "title", "description". 
      Only return the raw JSON array. Use reliable sources like The Hindu, Times of India, or local Tamil Nadu news portals.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: {
          tools: [{ googleSearch: {} }],
        },
      });

      const text = response.text || "";
      const jsonMatch = text.match(/\[[\s\S]*\]/);
      if (jsonMatch) {
        const items = JSON.parse(jsonMatch[0]);
        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
        const itemsWithUrls = items.map((item: any, index: number) => {
          const url = groundingChunks[index]?.web?.uri || groundingChunks[0]?.web?.uri;
          return { ...item, url };
        });
        setNewsItems(itemsWithUrls);
      } else {
        throw new Error("Could not parse news data.");
      }
    } catch (e) {
      console.error("News fetch failed", e);
      setError(`Failed to fetch latest news for ${city}. Showing general updates.`);
      setNewsItems([
        {
          source: 'Local Update',
          title: `${city} City Development Update`,
          description: `Recent discussions in ${city} focused on urban infrastructure and public amenities improvements.`
