        <div className="flex items-center gap-4">
          <button 
            onClick={onBack}
            className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition-colors"
          >
            <ArrowLeft size={24} className="text-gray-600 dark:text-gray-400" />
          </button>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 flex items-center justify-center">
              <svg width="32" height="32" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
                <circle cx="50" cy="50" r="50" fill="#f97316" />
                <circle cx="50" cy="50" r="35" stroke="white" strokeWidth="6" />
                <path d="M62 38 A 15 15 0 1 0 62 62" stroke="white" strokeWidth="7" strokeLinecap="round" fill="none" />
              </svg>
            </div>
            <div>
              <h1 className="text-xl font-black text-[#f97316] leading-none">{city} Updates</h1>
              <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-wider">Live News & Videos</p>
            </div>
          </div>
        </div>

        <button 
          onClick={fetchRealtimeNews}
          disabled={isRefreshing}
          className="flex items-center gap-2 px-5 py-2.5 bg-orange-50 dark:bg-orange-900/10 text-orange-600 dark:text-orange-400 rounded-2xl font-black text-sm hover:bg-orange-100 dark:hover:bg-orange-900/20 transition-all active:scale-95 disabled:opacity-50"
        >
          {isRefreshing ? (
            <Loader2 size={18} className="animate-spin" />
          ) : (
            <RefreshCw size={18} />
          )}
          <span>Refresh {city} News</span>
        </button>
      </header>

      <div className="flex-1 overflow-y-auto p-6 md:p-10 custom-scrollbar">
        <div className="max-w-6xl mx-auto">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-3">
              <Newspaper className="text-[#f97316]" size={28} />
              <h2 className="text-2xl font-black text-[#f97316]">Latest from {city}</h2>
            </div>
            {isRefreshing && (
              <span className="text-xs font-bold text-orange-500 animate-pulse tracking-widest uppercase">Syncing...</span>
            )}
          </div>

          {error && (
            <div className="mb-6 p-4 bg-orange-50 dark:bg-orange-900/10 rounded-xl text-orange-700 dark:text-orange-300 text-sm font-bold border border-orange-100 dark:border-orange-900/30">
              {error}
