interface TripPlannerViewProps {
  messages: Message[];
  onSendMessage: (text: string) => void;
  onBack: () => void;
  city: string;
  isLoading: boolean;
}

interface PlanActivity {
  timeRange: string;
  title: string;
  description: string;
  type: 'morning' | 'lunch' | 'afternoon' | 'evening';
}

interface PlanDay {
  dayNumber: number;
  dayTitle: string;
  activities: PlanActivity[];
}

const TripPlannerView: React.FC<TripPlannerViewProps> = ({ 
  messages, 
  onSendMessage, 
  onBack, 
  city, 
  isLoading 
}) => {
  // Logic to parse itinerary from assistant messages
  const parsedPlan = useMemo(() => {
    const assistantMsg = [...messages].reverse().find(m => m.role === 'assistant');
    if (!assistantMsg) return null;

    const content = assistantMsg.content;
    const plan: { title: string, summary: string, days: PlanDay[] } = {
      title: `${city} Itinerary`,
      summary: '',
      days: []
    };

    // Very basic parsing logic for demonstration
    const lines = content.split('\n');
    let currentDay: PlanDay | null = null;
    let titleFound = false;

    lines.forEach(line => {
      const trimmed = line.trim();
      if (!trimmed) return;

      // Extract Summary/Title
      if (!titleFound && trimmed.length > 5 && !trimmed.startsWith('-')) {
        plan.summary = trimmed;
        titleFound = true;
        return;
      }

      // Detect Day headers
      const dayMatch = trimmed.match(/Day\s*(\d+)[:\s]*(.*)/i);
      if (dayMatch) {
        currentDay = {
          dayNumber: parseInt(dayMatch[1]),
          dayTitle: dayMatch[2] || 'Exploration',
          activities: []
        };
        plan.days.push(currentDay);
        return;
      }

      // Detect Activities
      const activityMatch = trimmed.match(/^[-*✦]\s*(.*?\d+[:.]\d+.*?[-–].*?\d+[:.]\d+.*?)\s*:\s*(.*)/i) || 
                          trimmed.match(/^[-*✦]\s*(.*?)\s*\((.*?)\)\s*:\s*(.*)/i);

      if (activityMatch && currentDay) {
        currentDay.activities.push({
          timeRange: activityMatch[2] || activityMatch[1],
          title: activityMatch[1] || 'Activity',
          description: activityMatch[3] || trimmed,
          type: 'morning' // simplified
        });
      } else if (trimmed.startsWith('-') && currentDay) {
        // Fallback for simple bullets
        currentDay.activities.push({
          timeRange: 'Ongoing',
          title: trimmed.replace(/^[-*✦]\s*/, '').split(':')[0],
          description: trimmed.replace(/^[-*✦]\s*/, '').split(':')[1] || trimmed,
          type: 'morning'
        });
      }
    });

    return plan.days.length > 0 ? plan : null;
  }, [messages, city]);

  const handleDownload = () => {
    const transcript = messages.map(m => `${m.role.toUpperCase()}: ${m.content}`).join('\n\n');
    const blob = new Blob([transcript], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `itinerary_${city.toLowerCase()}.txt`;
    link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="flex-1 flex flex-col md:flex-row bg-white dark:bg-[#0c0c0e] animate-in fade-in duration-500 overflow-hidden">
      {/* Left Pane: Chat UI */}
      <div className="w-full md:w-1/2 flex flex-col border-r border-gray-100 dark:border-gray-800 relative z-10 shadow-xl md:shadow-none">
        <header className="px-6 py-4 flex items-center justify-between bg-white dark:bg-[#0c0c0e] border-b border-gray-100 dark:border-gray-800 shrink-0">
          <div className="flex items-center gap-4">
            <button 
              onClick={onBack}
              className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition-colors"
            >
              <ArrowLeft size={24} className="text-gray-600 dark:text-gray-400" />
            </button>
            <div className="flex items-center gap-3">
              <div className="w-9 h-9 flex items-center justify-center">
                <svg width="28" height="28" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <circle cx="50" cy="50" r="50" fill="#f97316" />
                  <circle cx="50" cy="50" r="35" stroke="white" strokeWidth="6" />
                  <path d="M62 38 A 15 15 0 1 0 62 62" stroke="white" strokeWidth="7" strokeLinecap="round" fill="none" />
                </svg>
              </div>
              <div>
                <h1 className="text-lg font-black text-orange-600 dark:text-orange-500 leading-none">Trip Planner</h1>
                <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase tracking-wider">Create your {city} itinerary</p>
              </div>
            </div>
          </div>
          <button 
            onClick={handleDownload}
            className="p-2 text-slate-400 hover:text-orange-500 transition-colors"
            title="Download Itinerary"
          >
            <Download size={22} />
          </button>
        </header>

        <div className="flex-1 overflow-hidden flex flex-col">
          <ChatWindow 
            messages={messages} 
            onSuggestionClick={onSendMessage} 
            isLoading={isLoading} 
          />
          <div className="p-4 border-t border-gray-50 dark:border-gray-900 bg-white/50 dark:bg-black/20">
            <InputBar 
              onSendMessage={onSendMessage} 
              onStartLive={() => {}} 
              onOpenImageGen={() => {}} 
              isLoading={isLoading} 
            />
          </div>
        </div>
      </div>

      {/* Right Pane: Structured Itinerary Preview */}
      <div className="hidden md:flex flex-1 flex-col bg-[#FDFBF9] dark:bg-[#08080a] overflow-y-auto custom-scrollbar p-8 lg:p-12">
        {parsedPlan ? (
          <div className="max-w-2xl mx-auto w-full animate-in fade-in slide-in-from-right-8 duration-700">
            <h2 className="text-4xl font-black text-[#f97316] mb-4 leading-tight tracking-tight">
              {parsedPlan.title}
            </h2>
            <p className="text-slate-500 dark:text-slate-400 text-lg mb-12 leading-relaxed font-medium">
              {parsedPlan.summary}
            </p>

            <div className="space-y-12">
              {parsedPlan.days.map((day) => (
                <div key={day.dayNumber} className="space-y-6">
                  <div className="flex items-center gap-4 border-b border-orange-100 dark:border-orange-900/30 pb-4">
                    <span className="text-[#f97316] font-black text-2xl">Day {day.dayNumber}:</span>
                    <h3 className="text-2xl font-bold text-slate-800 dark:text-slate-100 tracking-tight">
                      {day.dayTitle}
                    </h3>
                  </div>

                  <div className="grid grid-cols-1 gap-4">
                    {day.activities.map((activity, aIdx) => (
                      <div key={aIdx} className="bg-white dark:bg-slate-900/50 p-6 rounded-3xl border border-gray-100 dark:border-gray-800 shadow-sm flex gap-5 group transition-all hover:shadow-md">
                        <div className="w-12 h-12 bg-orange-50 dark:bg-orange-900/20 rounded-2xl flex items-center justify-center shrink-0">
                          {activity.title.toLowerCase().includes('temple') ? <MapPin className="text-orange-500" size={24} /> : 
                           activity.title.toLowerCase().includes('idli') || activity.title.toLowerCase().includes('shop') ? <Utensils className="text-orange-500" size={24} /> :
                           <Briefcase className="text-orange-500" size={24} />}
                        </div>
                        <div className="flex-1 space-y-2">
                          <div className="flex items-center gap-2 text-slate-400 font-bold text-xs uppercase tracking-widest">
                            <Clock size={12} />
                            {activity.timeRange}
                          </div>
                          <h4 className="text-xl font-bold text-slate-800 dark:text-slate-200 group-hover:text-orange-600 transition-colors">
                            {activity.title}
                          </h4>
                          <p className="text-slate-500 dark:text-slate-400 text-sm leading-relaxed font-medium">
                            {activity.description}
                          </p>
                          <div className="pt-3 flex">
                            <a 
                              href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(activity.title + ' ' + city)}`}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="inline-flex items-center gap-2 text-orange-600 dark:text-orange-400 text-sm font-black hover:underline"
                            >
                              <Navigation size={14} />
                              Get Directions
                            </a>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-center p-12 animate-in fade-in duration-1000">
            <div className="w-32 h-32 bg-orange-50 dark:bg-orange-950/20 rounded-full flex items-center justify-center mb-8 relative">
              <div className="absolute inset-0 rounded-full border-2 border-orange-100 dark:border-orange-900/30 animate-ping opacity-20" />
              <Briefcase size={64} className="text-orange-200 dark:text-orange-900/40" strokeWidth={1.5} />
            </div>
            <h3 className="text-3xl font-black text-orange-600/40 dark:text-orange-500/20 mb-4 tracking-tight">
              Your Itinerary Will Appear Here
            </h3>
            <p className="text-slate-400 dark:text-slate-600 text-lg max-w-sm font-medium leading-relaxed">
              Chat with the AI to start building your personalized trip plan for {city}.
            </p>
          </div>
        )}
      </div>

      {/* Mobile Loading Overlay (only if needed in split view) */}
      {isLoading && (
        <div className="absolute inset-0 z-50 bg-white/40 dark:bg-black/40 backdrop-blur-[2px] pointer-events-none flex items-center justify-center md:hidden">
          <Loader2 className="text-orange-500 animate-spin" size={40} />
        </div>
      )}
    </div>
  );
};

