  onBack: () => void;
  city: string;
  isLoading: boolean;
}

interface PlanActivity {
  timeRange: string;
  title: string;
  description: string;
  type: 'morning' | 'lunch' | 'afternoon' | 'evening';
}

interface PlanDay {
  dayNumber: number;
  dayTitle: string;
  activities: PlanActivity[];
}

const TripPlannerView: React.FC<TripPlannerViewProps> = ({ 
  messages, 
  onSendMessage, 
  onBack, 
  city, 
  isLoading 
}) => {
  // Enhanced parsing logic for trip itineraries
  const parsedPlan = useMemo(() => {
    const assistantMsg = [...messages].reverse().find(m => m.role === 'assistant');
    if (!assistantMsg) return null;

    const content = assistantMsg.content;
    const plan: { title: string, summary: string, days: PlanDay[] } = {
      title: `${city} Discovery Plan`,
      summary: '',
      days: []
    };

    const lines = content.split('\n');
    let currentDay: PlanDay | null = null;
    let titleFound = false;

    lines.forEach(line => {
      const trimmed = line.trim();
      if (!trimmed) return;

      // Detect Summary
      if (!titleFound && trimmed.length > 10 && !trimmed.startsWith('-') && !trimmed.startsWith('*')) {
        plan.summary = trimmed.replace(/\*\*/g, '');
        titleFound = true;
        return;
      }

      // Detect Day headers (e.g., "Day 1: ...")
      const dayMatch = trimmed.match(/Day\s*(\d+)[:\s]*(.*)/i);
      if (dayMatch) {
        currentDay = {
          dayNumber: parseInt(dayMatch[1]),
          dayTitle: dayMatch[2].replace(/\*\*/g, '').trim() || 'City Exploration',
          activities: []
        };
        plan.days.push(currentDay);
        return;
      }

      // Detect Activities within a day
      // Matches pattern like "- 9:00 AM - 11:00 AM: Meenakshi Temple"
      const activityMatch = trimmed.match(/^[-*✦]\s*(.*?[:\s-].*?)\s*:\s*(.*)/i);

      if (activityMatch && currentDay) {
        const timeAndTitle = activityMatch[1].replace(/\*\*/g, '').trim();
        const description = activityMatch[2].replace(/\*\*/g, '').trim();

        currentDay.activities.push({
          timeRange: timeAndTitle.split(' ').slice(0, 2).join(' ') || 'Scheduled',
          title: timeAndTitle.includes('-') ? timeAndTitle.split('-')[1]?.trim() : timeAndTitle,
          description: description,
          type: 'morning'
        });
      } else if (trimmed.startsWith('-') && currentDay) {
        const parts = trimmed.replace(/^[-*✦]\s*/, '').split(':');
        currentDay.activities.push({
          timeRange: 'Ongoing',
          title: parts[0].replace(/\*\*/g, '').trim(),
          description: parts[1]?.replace(/\*\*/g, '').trim() || '',
          type: 'morning'
        });
      }
    });

    return plan.days.length > 0 ? plan : null;
  }, [messages, city]);

  const handleDownload = () => {
    const transcript = messages.map(m => `${m.role.toUpperCase()}: ${m.content}`).join('\n\n');
    const blob = new Blob([transcript], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Madurai_Itinerary_${Date.now()}.txt`;
    link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="flex-1 flex flex-col md:flex-row bg-[#FAFAFA] dark:bg-[#0c0c0e] animate-in fade-in duration-500 overflow-hidden relative">
