                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-center p-12 animate-in fade-in duration-1000">
              <div className="w-40 h-40 bg-orange-50 dark:bg-orange-950/20 rounded-[3rem] flex items-center justify-center mb-10 relative rotate-12">
