  timeRange: string;
  title: string;
  description: string;
  type: 'morning' | 'lunch' | 'afternoon' | 'evening';
}

interface PlanDay {
  dayNumber: number;
  dayTitle: string;
  activities: PlanActivity[];
}

const TripPlannerView: React.FC<TripPlannerViewProps> = ({ 
  messages, 
  onSendMessage, 
  onSpeak,
  speakingMessageId,
