                        <Volume2 size={16} strokeWidth={2.5} />
                      )}
                    </button>
                  </>
                )}

                <div className={`text-[15px] md:text-[16.5px] whitespace-pre-wrap break-words tracking-tight ${msg.role === 'assistant' ? 'pb-4' : ''}`}>
                  {msg.role === 'assistant' ? (
                    <FormattedAssistantContent content={msg.content} />
