                    msg.content
                  )}
                </div>
              </div>

              <div className={`flex items-center gap-2 px-4 text-[10px] font-black tracking-widest uppercase opacity-40 ${
                msg.role === 'user' ? 'flex-row-reverse text-orange-900 dark:text-orange-200' : 'text-slate-500'
