  Navigation,
  Loader2,
  Calendar
} from 'lucide-react';
import { Message } from '../types';
import InputBar from './InputBar';
import ChatWindow from './ChatWindow';

interface TripPlannerViewProps {
  messages: Message[];
  onSendMessage: (text: string) => void;
  onSpeak: (text: string, id: string) => void;
  speakingMessageId: string | null;
  isTTSLoading?: string | null;
  onBack: () => void;
  city: string;
  isLoading: boolean;
}

interface PlanActivity {
  timeRange: string;
  title: string;
  description: string;
  type: 'morning' | 'lunch' | 'afternoon' | 'evening';
}

interface PlanDay {
  dayNumber: number;
  dayTitle: string;
  activities: PlanActivity[];
}

const TripPlannerView: React.FC<TripPlannerViewProps> = ({ 
  messages, 
  onSendMessage, 
  onSpeak,
  speakingMessageId,
  isTTSLoading,
  onBack, 
  city, 
  isLoading 
}) => {
  // Enhanced parsing logic for trip itineraries
  const parsedPlan = useMemo(() => {
    const assistantMsg = [...messages].reverse().find(m => m.role === 'assistant');
    if (!assistantMsg) return null;

    const content = assistantMsg.content;
    const plan: { title: string, summary: string, days: PlanDay[] } = {
      title: `${city} Discovery Plan`,
      summary: '',
      days: []
    };

    const lines = content.split('\n');
    let currentDay: PlanDay | null = null;
    let titleFound = false;

    lines.forEach(line => {
      const trimmed = line.trim();
      if (!trimmed) return;

      // Detect Summary
      if (!titleFound && trimmed.length > 10 && !trimmed.startsWith('-') && !trimmed.startsWith('*')) {
        plan.summary = trimmed.replace(/\*\*/g, '');
        titleFound = true;
        return;
      }

      // Detect Day headers (e.g., "Day 1: ...")
      const dayMatch = trimmed.match(/Day\s*(\d+)[:\s]*(.*)/i);
      if (dayMatch) {
        currentDay = {
          dayNumber: parseInt(dayMatch[1]),
          dayTitle: dayMatch[2].replace(/\*\*/g, '').trim() || 'City Exploration',
          activities: []
        };
        plan.days.push(currentDay);
        return;
      }

      // Detect Activities within a day
      const activityMatch = trimmed.match(/^[-*✦]\s*(.*?[:\s-].*?)\s*:\s*(.*)/i);

      if (activityMatch && currentDay) {
        const timeAndTitle = activityMatch[1].replace(/\*\*/g, '').trim();
        const description = activityMatch[2].replace(/\*\*/g, '').trim();

        currentDay.activities.push({
          timeRange: timeAndTitle.split(' ').slice(0, 2).join(' ') || 'Scheduled',
          title: timeAndTitle.includes('-') ? timeAndTitle.split('-')[1]?.trim() : timeAndTitle,
          description: description,
          type: 'morning'
        });
      } else if (trimmed.startsWith('-') && currentDay) {
        const parts = trimmed.replace(/^[-*✦]\s*/, '').split(':');
        currentDay.activities.push({
          timeRange: 'Ongoing',
          title: parts[0].replace(/\*\*/g, '').trim(),
          description: parts[1]?.replace(/\*\*/g, '').trim() || '',
          type: 'morning'
        });
      }
    });

    return plan.days.length > 0 ? plan : null;
  }, [messages, city]);

  const handleDownload = () => {
    const transcript = messages.map(m => `${m.role.toUpperCase()}: ${m.content}`).join('\n\n');
    const blob = new Blob([transcript], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Madurai_Itinerary_${Date.now()}.txt`;
    link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="flex-1 flex flex-col md:flex-row bg-[#FAFAFA] dark:bg-[#0c0c0e] animate-in fade-in duration-500 overflow-hidden relative">
      <div className="w-full md:w-[45%] lg:w-[40%] flex flex-col border-r border-gray-200/50 dark:border-gray-800 relative z-10 bg-white dark:bg-[#0c0c0e] shadow-2xl md:shadow-none">
        <header className="px-6 py-5 flex items-center justify-between bg-white dark:bg-[#0c0c0e] border-b border-gray-100 dark:border-gray-800 shrink-0">
          <div className="flex items-center gap-4">
            <button 
              onClick={onBack}
              className="p-2 hover:bg-orange-50 dark:hover:bg-orange-950/20 rounded-xl transition-all group"
              title="Return to City Guide"
            >
              <ArrowLeft size={22} className="text-gray-500 group-hover:text-orange-600 transition-colors" />
            </button>
            <div className="flex items-center gap-3">
              <div className="w-9 h-9 flex items-center justify-center bg-orange-100/50 dark:bg-orange-900/20 rounded-xl">
                <Calendar size={18} className="text-orange-600" />
              </div>
              <div>
                <h1 className="text-lg font-black text-slate-800 dark:text-slate-100 leading-none">Trip Planner</h1>
                <p className="text-[10px] font-bold text-orange-500 mt-1 uppercase tracking-[0.15em]">Live Itinerary Session</p>
              </div>
            </div>
          </div>
          <button 
            onClick={handleDownload}
            className="p-2.5 text-slate-400 hover:text-orange-600 hover:bg-orange-50 dark:hover:bg-orange-950/20 rounded-xl transition-all"
            title="Download Plan"
          >
            <Download size={20} />
          </button>
        </header>

        <div className="flex-1 overflow-hidden flex flex-col">
          <ChatWindow 
            messages={messages} 
            onSuggestionClick={onSendMessage} 
            onSpeak={onSpeak}
            speakingMessageId={speakingMessageId}
            isTTSLoading={isTTSLoading}
            isLoading={isLoading} 
          />
          <div className="p-4 border-t border-gray-100 dark:border-gray-900 bg-white/80 dark:bg-black/40 backdrop-blur-md">
            <InputBar 
              onSendMessage={handleSendMessage} 
              onStartLive={() => {}} 
              onOpenImageGen={() => {}} 
              isLoading={isLoading} 
            />
          </div>
        </div>
      </div>

      <div className="hidden md:flex flex-1 flex-col bg-[#FDFBF9] dark:bg-[#08080a] overflow-y-auto custom-scrollbar relative">
        <div className="absolute top-0 right-0 w-64 h-64 bg-orange-500/5 rounded-full blur-3xl -mr-32 -mt-32 pointer-events-none" />
        <div className="p-8 lg:p-16 max-w-3xl mx-auto w-full z-10">
          {parsedPlan ? (
            <div className="animate-in fade-in slide-in-from-right-10 duration-700">
              <div className="flex items-start justify-between mb-8">
                <div>
                  <h2 className="text-4xl lg:text-5xl font-black text-slate-900 dark:text-white mb-4 leading-tight tracking-tight">
                    {parsedPlan.title}
                  </h2>
                  <p className="text-slate-500 dark:text-slate-400 text-lg lg:text-xl leading-relaxed font-medium max-w-xl">
                    {parsedPlan.summary || `Personalized city adventure designed for you.`}
                  </p>
                </div>
              </div>

              <div className="space-y-16 mt-12">
                {parsedPlan.days.map((day) => (
                  <div key={day.dayNumber} className="relative">
                    <div className="flex items-center gap-6 mb-8">
                      <div className="w-16 h-16 bg-orange-600 rounded-2xl flex flex-col items-center justify-center text-white shadow-xl shadow-orange-200 dark:shadow-none">
                        <span className="text-[10px] font-black uppercase tracking-widest opacity-80">Day</span>
                        <span className="text-2xl font-black">{day.dayNumber}</span>
                      </div>
                      <div>
                        <h3 className="text-2xl lg:text-3xl font-black text-slate-800 dark:text-slate-100 tracking-tight">
                          {day.dayTitle}
                        </h3>
                        <p className="text-sm font-bold text-orange-500 uppercase tracking-widest mt-1">Daily Route</p>
                      </div>
                    </div>

                    <div className="space-y-6 relative ml-8 pl-10 border-l-2 border-orange-100 dark:border-orange-900/30">
                      {day.activities.map((activity, aIdx) => (
                        <div key={aIdx} className="relative group">
                          <div className="absolute -left-[51px] top-8 w-10 h-10 bg-white dark:bg-slate-900 border-2 border-orange-500 rounded-full flex items-center justify-center z-10 shadow-sm group-hover:scale-110 transition-transform">
                             <div className="w-2 h-2 bg-orange-500 rounded-full" />
                          </div>
                          <div className="bg-white dark:bg-slate-900 p-7 rounded-[2.5rem] border border-gray-100 dark:border-gray-800 shadow-sm transition-all hover:shadow-xl hover:border-orange-100 dark:hover:border-orange-900/30">
                            <div className="flex items-center gap-2 text-orange-600 dark:text-orange-400 font-black text-xs uppercase tracking-widest mb-3">
                              <Clock size={14} className="stroke-[3]" />
                              {activity.timeRange}
                            </div>
                            <h4 className="text-xl lg:text-2xl font-black text-slate-800 dark:text-slate-100 mb-3 leading-tight group-hover:text-orange-600 transition-colors">
                              {activity.title}
                            </h4>
                            <p className="text-slate-500 dark:text-slate-400 text-[15px] leading-relaxed font-medium mb-6">
                              {activity.description}
                            </p>
                            <div className="pt-4 border-t border-gray-50 dark:border-gray-800 flex">
                              <a 
                                href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(activity.title + ' ' + city)}`}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="inline-flex items-center gap-2.5 px-4 py-2 bg-slate-50 dark:bg-slate-800 hover:bg-orange-500 hover:text-white dark:hover:bg-orange-600 rounded-xl text-slate-600 dark:text-slate-300 text-xs font-black uppercase tracking-widest transition-all"
                              >
                                <Navigation size={14} />
                                Get Directions
                              </a>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-center p-12 animate-in fade-in duration-1000">
              <div className="w-40 h-40 bg-orange-50 dark:bg-orange-950/20 rounded-[3rem] flex items-center justify-center mb-10 relative rotate-12">
                <div className="absolute inset-0 rounded-[3rem] border-2 border-orange-100 dark:border-orange-900/30 animate-ping opacity-20" />
                <Briefcase size={80} className="text-orange-200 dark:text-orange-900/40" strokeWidth={1} />
              </div>
              <h3 className="text-4xl font-black text-slate-900/20 dark:text-white/10 mb-6 tracking-tight">
