              <p className="text-slate-400 dark:text-slate-600 text-xl max-w-sm font-medium leading-relaxed">
                As you chat with the AI, your structured itinerary will materialize here in real-time.
              </p>
              <div className="mt-12 flex items-center gap-3 p-4 bg-white dark:bg-slate-900 rounded-2xl border border-dashed border-gray-200 dark:border-gray-800 opacity-50">
                <Loader2 size={20} className="text-orange-500 animate-spin" />
                <span className="text-sm font-black text-slate-400 uppercase tracking-widest">Waiting for input...</span>
              </div>
            </div>
          )}
        </div>
      </div>
      {isLoading && (
        <div className="absolute inset-0 z-50 bg-white/30 dark:bg-black/30 backdrop-blur-[1px] pointer-events-none flex items-center justify-center md:hidden">
          <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-2xl flex items-center gap-4 border border-orange-100">
            <Loader2 className="text-orange-500 animate-spin" size={32} />
            <span className="font-black text-orange-600 uppercase tracking-widest text-sm">Building...</span>
          </div>
        </div>
      )}
    </div>
  );
};

