                <div className="absolute inset-0 rounded-[3rem] border-2 border-orange-100 dark:border-orange-900/30 animate-ping opacity-20" />
                <Briefcase size={80} className="text-orange-200 dark:text-orange-900/40" strokeWidth={1} />
              </div>
              <h3 className="text-4xl font-black text-slate-900/20 dark:text-white/10 mb-6 tracking-tight">
                Crafting Your City Experience
