import React, { useState, useEffect, useMemo } from 'react';
import { 
  ArrowLeft, 
  Download, 
  MapPin, 
  Briefcase, 
  Utensils, 
  Clock, 
  Navigation,
  Loader2,
  Calendar,
  Compass
} from 'lucide-react';
import { Message } from '../types';
import InputBar from './InputBar';
import ChatWindow from './ChatWindow';

interface TripPlannerViewProps {
  messages: Message[];
  onSendMessage: (text: string) => void;
  onSpeak: (text: string, id: string) => void;
  speakingMessageId: string | null;
  isTTSLoading?: string | null;
  onBack: () => void;
  city: string;
  isLoading: boolean;
}

interface PlanActivity {
  timeRange: string;
  title: string;
  description: string;
  type: 'temple' | 'food' | 'shopping' | 'general';
}

interface PlanDay {
  dayNumber: number;
  dayTitle: string;
  activities: PlanActivity[];
}

const TripPlannerView: React.FC<TripPlannerViewProps> = ({ 
  messages, 
  onSendMessage, 
  onSpeak,
  speakingMessageId,
  isTTSLoading,
  onBack, 
  city, 
  isLoading 
}) => {
  // Enhanced parsing logic for trip itineraries
  const parsedPlan = useMemo(() => {
    const assistantMsg = [...messages].reverse().find(m => m.role === 'assistant');
    if (!assistantMsg) return null;

    const content = assistantMsg.content;
    const plan: { title: string, summary: string, days: PlanDay[] } = {
      title: `${city} Discovery Plan`,
      summary: '',
      days: []
    };

    const lines = content.split('\n');
    let currentDay: PlanDay | null = null;
    let titleFound = false;

    lines.forEach(line => {
      const trimmed = line.trim();
      if (!trimmed) return;

      // Detect Summary/Title
      if (!titleFound && trimmed.length > 10 && !trimmed.startsWith('-') && !trimmed.startsWith('*')) {
        plan.title = trimmed.replace(/\*\*/g, '');
        titleFound = true;
        return;
      }

      if (titleFound && !plan.summary && !trimmed.match(/Day\s*\d+/i) && !trimmed.startsWith('-')) {
        plan.summary = trimmed.replace(/\*\*/g, '');
      }

      // Detect Day headers (e.g., "Day 1: ...")
      const dayMatch = trimmed.match(/Day\s*(\d+)[:\s]*(.*)/i);
      if (dayMatch) {
        currentDay = {
          dayNumber: parseInt(dayMatch[1]),
          dayTitle: dayMatch[2].replace(/\*\*/g, '').trim() || 'City Exploration',
          activities: []
        };
        plan.days.push(currentDay);
        return;
      }

      // Detect Activities within a day
      const activityMatch = trimmed.match(/^[-*✦]\s*(.*?[:\s-].*?)\s*:\s*(.*)/i);

      if (activityMatch && currentDay) {
        const timeAndTitle = activityMatch[1].replace(/\*\*/g, '').trim();
        const description = activityMatch[2].replace(/\*\*/g, '').trim();

        let type: PlanActivity['type'] = 'general';
        const lowerTitle = timeAndTitle.toLowerCase();
        if (lowerTitle.includes('temple')) type = 'temple';
        else if (lowerTitle.includes('food') || lowerTitle.includes('idli') || lowerTitle.includes('lunch') || lowerTitle.includes('dinner')) type = 'food';
        else if (lowerTitle.includes('shop')) type = 'shopping';

        currentDay.activities.push({
          timeRange: timeAndTitle.split(' ').slice(0, 2).join(' ') || 'Scheduled',
          title: timeAndTitle.includes('-') ? timeAndTitle.split('-')[1]?.trim() : timeAndTitle,
          description: description,
          type
        });
      }
    });

    return plan.days.length > 0 ? plan : null;
  }, [messages, city]);

  const handleDownload = () => {
    const transcript = messages.map(m => `${m.role.toUpperCase()}: ${m.content}`).join('\n\n');
    const blob = new Blob([transcript], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Madurai_Itinerary_${Date.now()}.txt`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const getActivityIcon = (type: PlanActivity['type']) => {
    switch(type) {
      case 'temple': return '🛕';
      case 'food': return '🍜';
      case 'shopping': return '🛍️';
      default: return '📍';
    }
  };

  return (
    <div className="flex-1 flex flex-col md:flex-row bg-[#FAFAFA] dark:bg-[#0c0c0e] animate-in fade-in duration-500 overflow-hidden relative">
      {/* Left Chat Column */}
      <div className="w-full md:w-[450px] flex flex-col border-r border-gray-200 dark:border-gray-800 relative z-10 bg-white dark:bg-[#0c0c0e] shadow-lg shrink-0">
        <header className="px-5 py-4 flex items-center justify-between bg-white dark:bg-[#0c0c0e] border-b border-gray-100 dark:border-gray-800 shrink-0">
          <div className="flex items-center gap-3">
            <button onClick={onBack} className="p-1.5 hover:bg-orange-50 dark:hover:bg-orange-950/20 rounded-lg transition-all group">
              <ArrowLeft size={20} className="text-gray-500 group-hover:text-orange-600" />
            </button>
            <div className="flex items-center gap-2.5">
              <div className="w-8 h-8 flex items-center justify-center bg-orange-500 rounded-full shadow-sm">
                <Compass size={18} className="text-white" />
              </div>
              <div>
                <h1 className="text-[15px] font-extrabold text-[#c2410c] dark:text-orange-400 leading-tight">Trip Planner</h1>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wide">Create your {city} itinerary</p>
              </div>
            </div>
          </div>
          <button onClick={handleDownload} className="p-2 text-gray-400 hover:text-orange-600 transition-all">
            <Download size={18} />
          </button>
        </header>

        <div className="flex-1 overflow-hidden flex flex-col bg-[#F9F9F9] dark:bg-[#0a0a0c]">
          <ChatWindow 
            messages={messages} 
            onSuggestionClick={onSendMessage} 
            onSpeak={onSpeak}
            speakingMessageId={speakingMessageId}
            isTTSLoading={isTTSLoading}
            isLoading={isLoading} 
          />
          <div className="p-3 border-t border-gray-200 dark:border-gray-800 bg-white/50 dark:bg-black/20 backdrop-blur-md">
            <InputBar 
              onSendMessage={onSendMessage} 
              onStartLive={() => {}} 
              onOpenImageGen={() => {}} 
              isLoading={isLoading} 
            />
          </div>
        </div>
      </div>

      {/* Right Itinerary Column */}
      <div className="flex-1 flex flex-col bg-white dark:bg-[#08080a] overflow-y-auto custom-scrollbar relative">
        <div className="p-8 md:p-12 lg:p-16 max-w-4xl mx-auto w-full z-10">
          {parsedPlan ? (
            <div className="animate-in fade-in slide-in-from-right-10 duration-700">
              <div className="mb-10">
                <h2 className="text-[32px] md:text-[40px] font-black text-[#853517] dark:text-orange-200 mb-4 leading-[1.15] tracking-tight">
                  {parsedPlan.title}
                </h2>
                <p className="text-[#5f6368] dark:text-gray-400 text-[16px] md:text-[17px] leading-relaxed font-medium">
                  {parsedPlan.summary || `Experience the best of ${city} with this curated plan.`}
                </p>
              </div>

              <div className="space-y-12">
                {parsedPlan.days.map((day) => (
                  <div key={day.dayNumber}>
                    <div className="flex items-center gap-3 mb-6">
                      <h3 className="text-[20px] md:text-[22px] font-black text-[#c2410c] dark:text-orange-500 tracking-tight">
                        Day {day.dayNumber}: {day.dayTitle}
                      </h3>
                      <div className="flex-1 h-[1px] bg-orange-100 dark:bg-orange-900/30 ml-2" />
                    </div>

                    <div className="grid grid-cols-1 gap-6">
                      {day.activities.map((activity, aIdx) => (
                        <div key={aIdx} className="bg-white dark:bg-[#111] p-6 md:p-8 rounded-2xl border border-gray-100 dark:border-gray-800 shadow-sm transition-all hover:shadow-md">
                          <div className="flex items-start gap-5">
                            <div className="w-12 h-12 md:w-14 md:h-14 bg-[#fff7ed] dark:bg-orange-950/30 rounded-full flex items-center justify-center text-2xl md:text-3xl shrink-0 shadow-inner">
                              {getActivityIcon(activity.type)}
                            </div>
                            <div className="flex-1">
                              <div className="flex items-center gap-1.5 text-[#5f6368] dark:text-gray-400 text-[12px] font-bold uppercase tracking-wider mb-1">
                                <Clock size={12} className="text-orange-400" />
                                {activity.timeRange}
                              </div>
                              <h4 className="text-[18px] md:text-[20px] font-black text-slate-800 dark:text-slate-100 mb-2 leading-tight">
                                {activity.title}
                              </h4>
                              <p className="text-slate-500 dark:text-slate-400 text-[14px] md:text-[15px] leading-relaxed font-medium mb-6">
                                {activity.description}
                              </p>

                              <div className="flex justify-center border-t border-gray-50 dark:border-gray-800/50 pt-5">
                                <a 
                                  href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(activity.title + ' ' + city)}`}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  className="inline-flex items-center gap-2 text-[#c2410c] dark:text-orange-400 font-black text-[13px] uppercase tracking-widest hover:opacity-80 transition-all"
                                >
                                  <MapPin size={16} />
                                  Get Directions
                                </a>
                              </div>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div className="h-full min-h-[500px] flex flex-col items-center justify-center text-center p-8 animate-in fade-in duration-1000">
              <div className="w-48 h-48 bg-[#fff7ed] dark:bg-orange-950/20 rounded-[48px] flex items-center justify-center mb-10 relative shadow-sm">
                <Briefcase size={80} className="text-orange-200 dark:text-orange-900/40" strokeWidth={1.5} />
              </div>
              <h3 className="text-[34px] md:text-[42px] font-black text-[#bdc1c6] dark:text-gray-800 mb-6 tracking-tight leading-tight">
                Crafting Your City Experience
              </h3>
              <p className="text-[#80868b] dark:text-gray-600 text-[17px] md:text-[18px] max-w-sm font-medium leading-relaxed mb-12">
                As you chat with the AI, your structured itinerary will materialize here in real-time.
              </p>

              <div className="px-8 py-3.5 bg-white dark:bg-[#111] rounded-full border border-gray-100 dark:border-gray-800 shadow-sm flex items-center gap-3.5">
                <div className="w-4 h-4 border-2 border-orange-200 border-t-orange-500 rounded-full animate-spin" />
                <span className="text-[12px] font-black text-[#bdc1c6] uppercase tracking-[0.2em]">Waiting for input...</span>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

