    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const contents = [
      ...history.map(h => ({ role: h.role, parts: h.parts })),
      { role: 'user', parts: [{ text: userMessage }] }
    ];

    if (onChunk) {
      const result = await ai.models.generateContentStream({
        model: 'gemini-3-flash-preview',
        contents,
        config: {
          systemInstruction: getSystemInstruction(city),
          temperature: 0.7,
          tools: [{ googleSearch: {} }],
        },
      });

      let fullText = "";
      for await (const chunk of result) {
        const text = chunk.text;
        if (text) {
          fullText += text;
          onChunk(fullText);
        }
      }
      return fullText;
    } else {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents,
        config: {
          systemInstruction: getSystemInstruction(city),
          temperature: 0.7,
          tools: [{ googleSearch: {} }],
        },
      });
      return response.text || "I'm sorry, I couldn't process that request.";
    }
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "I am having trouble connecting to my knowledge base. Please check your internet or try again later.";
  }
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ChatWindow from './components/ChatWindow';
import InputBar from './components/InputBar';
import LoginModal from './components/LoginModal';
import CitySelector from './components/CitySelector';
import ImageGenModal from './components/ImageGenModal';
import NewsView from './components/NewsView';
import StatsView from './components/StatsView';
import AboutView from './components/AboutView';
import PromoteModal from './components/PromoteModal';
import TripPlannerView from './components/TripPlannerView';
import { Message, ChatHistory } from './types';
import { getGeminiResponse } from './services/geminiService';
import { 
  Moon, 
  Sun, 
  Cloud, 
  X, 
  Volume2, 
  Mic, 
  RefreshCw, 
  ChevronDown, 
  CloudRain, 
  CloudLightning 
} from 'lucide-react';
import { SUBTITLE, SUGGESTIONS } from './constants';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';

const encode = (bytes: Uint8Array) => {
  let binary = '';
  for (let i = 0; i < bytes.byteLength; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
};

const decode = (base64: string) => {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
};

const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number) => {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
  }
  return buffer;
};

const App: React.FC = () => {
  const [selectedCity, setSelectedCity] = useState('Madurai');
  const [currentView, setCurrentView] = useState<'chat' | 'news' | 'stats' | 'about' | 'trip-planner'>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isCitySelectorOpen, setIsCitySelectorOpen] = useState(false);
  const [isImageGenOpen, setIsImageGenOpen] = useState(false);
  const [isPromoteOpen, setIsPromoteOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([]);
  const [history, setHistory] = useState<ChatHistory[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [isLoginOpen, setIsLoginOpen] = useState(false);
  const [messagesSent, setMessagesSent] = useState(0);

  // Weather State
  const [weather, setWeather] = useState({ temp: '--', condition: 'Loading...' });
  const [isWeatherRefreshing, setIsWeatherRefreshing] = useState(false);

  // TTS State
  const [speakingMessageId, setSpeakingMessageId] = useState<string | null>(null);
  const [isTTSLoading, setIsTTSLoading] = useState<string | null>(null);
  const currentAudioSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioCacheRef = useRef<Map<string, AudioBuffer>>(new Map());

  // Live Mode State
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [liveTranscription, setLiveTranscription] = useState('');
  const liveSessionRef = useRef<any>(null);
  const liveAudioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const liveNextStartTimeRef = useRef(0);
  const liveSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Initialize and Pre-warm AudioContext on first user gesture
  useEffect(() => {
    const warmAudio = () => {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      if (audioContextRef.current.state === 'suspended') {
        audioContextRef.current.resume();
      }
      window.removeEventListener('click', warmAudio);
      window.removeEventListener('keydown', warmAudio);
    };
    window.addEventListener('click', warmAudio);
    window.addEventListener('keydown', warmAudio);
    return () => {
      window.removeEventListener('click', warmAudio);
      window.removeEventListener('keydown', warmAudio);
    };
  }, []);

  // Handle Dark Mode
  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  const handleRefreshWeather = useCallback(async (city: string) => {
    if (isWeatherRefreshing) return;
    setIsWeatherRefreshing(true);
    try {
      const prompt = `What is the current temperature and short sky condition in ${city}, Tamil Nadu right now? Reply ONLY with JSON: {"temp": "number", "condition": "brief"}`;
      const response = await getGeminiResponse(prompt, [], city);
      try {
        const cleaned = response.replace(/```json|```/g, '').trim();
        const data = JSON.parse(cleaned);
        if (data.temp && data.condition) {
          setWeather({ temp: data.temp.toString().replace('°C', ''), condition: data.condition });
        }
      } catch {
        const tempMatch = response.match(/(\d+)/);
        if (tempMatch) {
          setWeather(prev => ({ ...prev, temp: tempMatch[1] }));
        }
      }
    } catch (e) {
      console.error("Weather refresh failed", e);
    } finally {
      setIsWeatherRefreshing(false);
    }
  }, [isWeatherRefreshing]);

  useEffect(() => {
    handleRefreshWeather(selectedCity);
  }, [selectedCity]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  const handleSendMessage = useCallback(async (text: string, files?: { data: string, mimeType: string }[]) => {
    const isTripRequest = SUGGESTIONS.some(s => s.prompt === text && s.title.toLowerCase().includes('trip'));

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setMessagesSent(prev => prev + 1);
    setIsLoading(true);

    if (isTripRequest) {
      setCurrentView('trip-planner');
    } else if (currentView !== 'trip-planner') {
      setCurrentView('chat');
    }

    const chatHistoryForAPI = messages.map(m => ({
      role: m.role === 'assistant' ? 'model' as const : 'user' as const,
      parts: [{ text: m.content }]
    }));

    // Create placeholder message for assistant
    const assistantMsgId = (Date.now() + 1).toString();
    const assistantMsgPlaceholder: Message = {
      id: assistantMsgId,
      role: 'assistant',
      content: '',
      timestamp: new Date()
    };
    setMessages(prev => [...prev, assistantMsgPlaceholder]);

    await getGeminiResponse(text, chatHistoryForAPI, selectedCity, (chunk) => {
      setMessages(prev => prev.map(m => m.id === assistantMsgId ? { ...m, content: chunk } : m));
    });

    setIsLoading(false);

    if (messages.length === 0 || isTripRequest) {
      const historyId = Date.now().toString();
      setHistory(prev => [{
        id: historyId,
        title: text.length > 25 ? text.substring(0, 25) + '...' : text,
        lastUpdated: new Date()
      }, ...prev]);
    }
  }, [messages, selectedCity, currentView]);

  const handleDeleteHistory = (id: string) => {
    setHistory(prev => prev.filter(item => item.id !== id));
  };

  const handleDownloadHistory = (id: string) => {
    const chat = history.find(h => h.id === id);
    if (!chat) return;
    const transcript = messages.map(m => 
      `${m.role.toUpperCase()} (${m.timestamp.toLocaleTimeString()}):\n${m.content}\n`
    ).join('\n---\n\n');

    const blob = new Blob([transcript || "Chat history data placeholder"], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${chat.title.replace(/[^a-z0-9]/gi, '_').toLowerCase()}_transcript.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleSpeak = useCallback(async (text: string, id: string) => {
    if (speakingMessageId === id) {
      if (currentAudioSourceRef.current) {
        try { currentAudioSourceRef.current.stop(); } catch (e) {}
        currentAudioSourceRef.current = null;
      }
      setSpeakingMessageId(null);
      return;
    }

    if (currentAudioSourceRef.current) {
      try { currentAudioSourceRef.current.stop(); } catch (e) {}
      currentAudioSourceRef.current = null;
    }
    setSpeakingMessageId(null);

    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    if (audioContextRef.current.state === 'suspended') {
      await audioContextRef.current.resume();
    }

    const cachedBuffer = audioCacheRef.current.get(id);
    if (cachedBuffer) {
      const source = audioContextRef.current.createBufferSource();
      source.buffer = cachedBuffer;
      source.connect(audioContextRef.current.destination);
      source.onended = () => setSpeakingMessageId(prev => (prev === id ? null : prev));
      currentAudioSourceRef.current = source;
      setSpeakingMessageId(id);
      source.start();
      return;
    }

    setIsTTSLoading(id);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const cleanText = text
        .replace(/\[Location: (.*?)\]/g, '$1')
        .replace(/\*\*/g, '')
        .replace(/#/g, '')
        .trim();

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: cleanText }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const audioBuffer = await decodeAudioData(decode(base64Audio), audioContextRef.current, 24000, 1);
        audioCacheRef.current.set(id, audioBuffer);
        const source = audioContextRef.current.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(audioContextRef.current.destination);
        source.onended = () => {
          setSpeakingMessageId(prev => (prev === id ? null : prev));
        };
        currentAudioSourceRef.current = source;
        setIsTTSLoading(null);
        setSpeakingMessageId(id);
        source.start();
      } else {
        setIsTTSLoading(null);
        setSpeakingMessageId(null);
      }
    } catch (e) {
      console.error("TTS Error:", e);
      setIsTTSLoading(null);
      setSpeakingMessageId(null);
    }
  }, [speakingMessageId]);

  const handleUtilityAction = (action: 'news' | 'analytics' | 'promote' | 'about') => {
    setIsSidebarOpen(false);
    switch (action) {
      case 'news': setCurrentView('news'); break;
      case 'analytics': setCurrentView('stats'); break;
      case 'promote': setIsPromoteOpen(true); break;
      case 'about': setCurrentView('about'); break;
    }
  };

  const stopLiveMode = useCallback(() => {
    if (liveSessionRef.current) {
      liveSessionRef.current.close();
      liveSessionRef.current = null;
    }
    liveSourcesRef.current.forEach(s => { try { s.stop(); } catch (e) {} });
    liveSourcesRef.current.clear();
    if (liveAudioContextRef.current) {
      const { input, output } = liveAudioContextRef.current;
      if (input.state !== 'closed') input.close().catch(console.error);
      if (output.state !== 'closed') output.close().catch(console.error);
      liveAudioContextRef.current = null;
    }
    setIsLiveActive(false);
    setLiveTranscription('');
  }, []);

  const startLiveMode = useCallback(async () => {
    try {
      setIsLiveActive(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      liveAudioContextRef.current = { input: inputCtx, output: outputCtx };
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              sessionPromise.then(s => s.sendRealtimeInput({ media: { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (m: LiveServerMessage) => {
            const audioData = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              liveNextStartTimeRef.current = Math.max(liveNextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), outputCtx, 24000, 1);
              const source = outputCtx.createBufferSource();
              source.buffer = buffer;
              source.connect(outputCtx.destination);
              source.onended = () => liveSourcesRef.current.delete(source);
              source.start(liveNextStartTimeRef.current);
              liveNextStartTimeRef.current += buffer.duration;
              liveSourcesRef.current.add(source);
            }
            if (m.serverContent?.outputTranscription) setLiveTranscription(prev => prev + m.serverContent?.outputTranscription?.text);
            if (m.serverContent?.turnComplete) setLiveTranscription('');
          },
          onclose: () => stopLiveMode(),
          onerror: () => stopLiveMode()
        },
        config: {
          responseModalities: [Modality.AUDIO],
          systemInstruction: `You are ${selectedCity} Info AI. Natural voice mode. Be helpful but brief.`,
          outputAudioTranscription: {}
        }
      });
      liveSessionRef.current = await sessionPromise;
    } catch (e) {
      console.error(e);
      stopLiveMode();
    }
  }, [stopLiveMode, selectedCity]);

  const WeatherIcon = () => {
    const cond = weather.condition.toLowerCase();
    if (cond.includes('rain')) return <CloudRain size={28} className="text-blue-500" />;
    if (cond.includes('storm')) return <CloudLightning size={28} className="text-purple-500" />;
    if (cond.includes('sun') || cond.includes('clear')) return <Sun size={28} className="text-orange-400" />;
    return <Cloud size={28} className="text-slate-400" />;
  };

  const handleCitySelect = (city: string) => {
    setSelectedCity(city);
    setMessages([]); 
    setCurrentView('chat');
  };

  const onNewChat = () => {
    setMessages([]);
    setCurrentView('chat');
    setIsSidebarOpen(false);
  };

  return (
    <div className="flex h-screen overflow-hidden text-elegant-light dark:text-elegant-dark bg-[#FBF8F3] dark:bg-[#0F0D0C] relative transition-all duration-700 ease-in-out">
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/5 dark:bg-black/40 backdrop-blur-[1px] z-40" onClick={() => setIsSidebarOpen(false)} />
      )}

      <Sidebar 
        isOpen={isSidebarOpen} 
        onClose={() => setIsSidebarOpen(false)}
        history={history}
        onNewChat={onNewChat}
        onSelectHistory={() => { setCurrentView('chat'); setIsSidebarOpen(false); }}
        onDeleteHistory={handleDeleteHistory}
        onDownloadHistory={handleDownloadHistory}
        onUtilityAction={handleUtilityAction}
        onLogin={() => { setIsLoginOpen(true); setIsSidebarOpen(false); }}
      />

      <div className="flex-1 flex flex-col min-w-0 relative">
        {currentView !== 'trip-planner' && (
          <header className="h-24 flex items-center px-6 md:px-10 relative bg-white/30 dark:bg-black/20 backdrop-blur-md border-b border-orange-100/30 shrink-0">
            <div className="flex items-center absolute left-6 md:left-10">
              <button 
                onClick={(e) => { e.stopPropagation(); setIsSidebarOpen(!isSidebarOpen); }}
                className="w-12 h-12 flex items-center justify-center transition-all hover:scale-105 active:scale-95 focus:outline-none"
              >
                <div className="relative w-10 h-10 flex items-center justify-center">
                  <svg width="40" height="40" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <circle cx="50" cy="50" r="50" fill="#f97316" />
                    <circle cx="50" cy="50" r="35" stroke="white" strokeWidth="6" />
                    <path d="M62 38 A 15 15 0 1 0 62 62" stroke="white" strokeWidth="7" strokeLinecap="round" fill="none" />
                  </svg>
                </div>
              </button>
            </div>

            <div className="flex flex-col items-center justify-center w-full">
              <button 
                onClick={() => setIsCitySelectorOpen(true)}
                className="group flex flex-col items-center justify-center transition-all hover:opacity-80 active:scale-95 px-4 py-1 rounded-2xl hover:bg-orange-50/50 dark:hover:bg-orange-900/10"
              >
                <div className="flex items-center gap-1.5">
                  <h1 className="text-[26px] md:text-[28px] font-bold text-[#f97316] tracking-tight">{selectedCity} Info AI</h1>
                  <ChevronDown size={24} className="text-[#f97316] mt-1 transition-transform group-hover:translate-y-0.5" />
                </div>
                <p className="text-[12px] md:text-[13px] text-slate-500 font-medium tracking-wide">{SUBTITLE}</p>
              </button>
            </div>

            <div className="absolute right-6 md:right-10 flex items-center gap-4 md:gap-6">
               <button 
                 onClick={() => handleRefreshWeather(selectedCity)}
                 className={`hidden sm:flex items-center gap-2.5 transition-all p-2 rounded-xl hover:bg-white/50 dark:hover:bg-white/5 ${isWeatherRefreshing ? 'opacity-70' : ''}`}
                 title="Refresh weather"
               >
                  {isWeatherRefreshing ? (
                    <RefreshCw size={24} className="text-slate-500 animate-spin" />
                  ) : (
                    <WeatherIcon />
                  )}
                  <div className="flex flex-col items-start leading-none">
                    <span className="text-[17px] font-semibold text-slate-700 dark:text-slate-300">{weather.temp}°C</span>
                  </div>
               </button>
               <button 
                 onClick={toggleTheme}
                 className="p-2 text-slate-700 dark:text-orange-200 transition-all hover:scale-110 rounded-xl hover:bg-white/50 dark:hover:bg-white/5"
               >
                 {theme === 'light' ? <Moon size={28} /> : <Sun size={28} />}
               </button>
            </div>
          </header>
        )}

        <main className="flex-1 flex flex-col relative overflow-hidden" onClick={() => isSidebarOpen && setIsSidebarOpen(false)}>
          {currentView === 'chat' ? (
            <>
              <ChatWindow 
                messages={messages} 
                onSuggestionClick={handleSendMessage} 
                onSpeak={handleSpeak} 
                speakingMessageId={speakingMessageId}
                isTTSLoading={isTTSLoading}
                isLoading={isLoading} 
              />
              <div className="w-full">
                <InputBar 
                  onSendMessage={handleSendMessage} 
                  onStartLive={startLiveMode} 
                  onOpenImageGen={() => setIsImageGenOpen(true)}
                  isLoading={isLoading} 
                />
              </div>
            </>
          ) : currentView === 'news' ? (
            <NewsView onBack={() => setCurrentView('chat')} city={selectedCity} />
          ) : currentView === 'stats' ? (
            <StatsView onBack={() => setCurrentView('chat')} messageCount={messagesSent} />
          ) : currentView === 'trip-planner' ? (
            <TripPlannerView 
              messages={messages} 
              onSendMessage={handleSendMessage} 
              onSpeak={handleSpeak}
              speakingMessageId={speakingMessageId}
              isTTSLoading={isTTSLoading}
              onBack={() => { setMessages([]); setCurrentView('chat'); }} 
              city={selectedCity}
              isLoading={isLoading}
            />
          ) : (
            <AboutView onBack={() => setCurrentView('chat')} city={selectedCity} stats={{ visits: 2, questions: messagesSent, trips: 0 }} />
          )}
        </main>

        {isLiveActive && (
          <div className="fixed inset-0 z-[60] bg-[#f97316]/95 backdrop-blur-md flex flex-col items-center justify-center text-white p-8 animate-in fade-in zoom-in duration-300">
            <button onClick={stopLiveMode} className="absolute top-10 right-10 p-4 bg-white/10 hover:bg-white/20 rounded-full transition-all">
              <X size={36} />
            </button>
            <div className="w-56 h-56 bg-white/10 rounded-full flex items-center justify-center relative mb-16">
              <div className="absolute inset-0 rounded-full border-4 border-white/20 animate-ping" />
              <div className="absolute inset-4 rounded-full border-4 border-white/30 animate-ping delay-150" />
              <div className="w-36 h-36 bg-white rounded-full flex items-center justify-center shadow-2xl">
                <Volume2 size={72} className="text-[#f97316] animate-pulse" />
              </div>
            </div>
            <h2 className="text-4xl font-bold mb-6 tracking-tight">{selectedCity} Live AI</h2>
            <p className="text-orange-50 text-xl text-center max-w-lg font-medium leading-relaxed italic opacity-90 px-4">
              {liveTranscription || `Listening... Talk to me about ${selectedCity}.`}
            </p>
            <div className="mt-20 px-6 py-3 bg-white/10 rounded-full border border-white/20 flex items-center gap-3">
              <Mic size={20} className="text-green-300 animate-pulse" />
              <span className="text-xs font-bold tracking-[0.2em] uppercase">Session Active</span>
            </div>
          </div>
        )}

        <LoginModal isOpen={isLoginOpen} onClose={() => setIsLoginOpen(false)} />
        <CitySelector 
          isOpen={isCitySelectorOpen} 
          onClose={() => setIsCitySelectorOpen(false)} 
          onSelect={handleCitySelect}
          currentCity={selectedCity}
        />
        <ImageGenModal 
          isOpen={isImageGenOpen} 
          onClose={() => setIsImageGenOpen(false)} 
          city={selectedCity}
        />
        <PromoteModal 
          isOpen={isPromoteOpen} 
          onClose={() => setIsPromoteOpen(false)} 
          city={selectedCity}
        />
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useEffect } from 'react';
import { Message } from '../types';
import { SUGGESTIONS } from '../constants';
import { MapPin, Volume2, Pause, Loader2 } from 'lucide-react';

interface ChatWindowProps {
  messages: Message[];
  onSuggestionClick: (prompt: string) => void;
  onSpeak: (text: string, id: string) => void;
  speakingMessageId: string | null;
  isTTSLoading?: string | null;
  isLoading: boolean;
}

const AssistantLogo = ({ size = 20 }: { size?: number }) => (
  <div 
    className="rounded-full bg-[#1a1c1e] flex items-center justify-center" 
    style={{ width: size, height: size }}
  >
    <svg width={size * 0.7} height={size * 0.7} viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
      <path d="M12 4L4 12V20H20V12L12 4Z" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
