      <path d="M12 4C10 6 8 8 8 10" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
      <path d="M12 4C14 6 16 8 16 10" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    </svg>
  </div>
);

const TripPlannerView: React.FC<TripPlannerViewProps> = ({ 
  messages, 
  onSendMessage, 
  onSpeak,
  speakingMessageId,
  isTTSLoading,
  onBack, 
  city, 
  isLoading 
}) => {
  const parsedPlan = useMemo(() => {
    const assistantMsg = [...messages].reverse().find(m => m.role === 'assistant' && m.content);
    if (!assistantMsg) return null;

    const content = assistantMsg.content;
    const plan: { title: string, summary: string, days: PlanDay[] } = {
      title: `${city} Discovery Plan`,
      summary: '',
      days: []
    };

    const lines = content.split('\n');
    let currentDay: PlanDay | null = null;
    let titleFound = false;

    lines.forEach(line => {
      const trimmed = line.trim();
      if (!trimmed) return;

      if (!titleFound && trimmed.length > 5 && !trimmed.startsWith('-') && !trimmed.startsWith('*')) {
        plan.title = trimmed.replace(/\*\*/g, '');
        titleFound = true;
        return;
      }

      if (titleFound && !plan.summary && !trimmed.match(/Day\s*\d+/i) && !trimmed.startsWith('-')) {
        plan.summary = trimmed.replace(/\*\*/g, '');
      }

      const dayMatch = trimmed.match(/Day\s*(\d+)[:\s]*(.*)/i);
      if (dayMatch) {
        currentDay = {
          dayNumber: parseInt(dayMatch[1]),
          dayTitle: dayMatch[2].replace(/\*\*/g, '').trim() || 'City Exploration',
          activities: []
        };
        plan.days.push(currentDay);
        return;
      }

      const activityMatch = trimmed.match(/^[-*✦]\s*(.*?[:\s-].*?)\s*[:]\s*(.*)/i);

      if (activityMatch && currentDay) {
        const timeAndTitle = activityMatch[1].replace(/\*\*/g, '').trim();
        const description = activityMatch[2].replace(/\*\*/g, '').trim();

        let type: PlanActivity['type'] = 'general';
        const lowerTitle = timeAndTitle.toLowerCase();
        if (lowerTitle.includes('temple')) type = 'temple';
        else if (lowerTitle.includes('food') || lowerTitle.includes('idli') || lowerTitle.includes('lunch') || lowerTitle.includes('dinner')) type = 'food';
        else if (lowerTitle.includes('shop')) type = 'shopping';

        currentDay.activities.push({
          timeRange: timeAndTitle.split(' ').slice(0, 2).join(' ') || 'Scheduled',
          title: timeAndTitle.includes('-') ? timeAndTitle.split('-')[1]?.trim() : timeAndTitle,
          description,
          type
        });
      }
    });

    return plan.days.length > 0 ? plan : null;
  }, [messages, city]);

  const getActivityIcon = (type: PlanActivity['type']) => {
    switch(type) {
      case 'temple': return '🛕';
      case 'food': return '🍜';
      case 'shopping': return '🛍️';
      default: return '📍';
    }
  };

  return (
    <div className="flex-1 flex flex-col md:flex-row bg-[#FAFAFA] dark:bg-[#0c0c0e] animate-in fade-in duration-500 overflow-hidden relative">
      {/* Left Chat Column */}
      <div className="w-full md:w-[450px] flex flex-col border-r border-gray-200 dark:border-gray-800 relative z-10 bg-[#f9f9f9] dark:bg-[#0c0c0e] shadow-lg shrink-0">
        <header className="px-5 py-4 flex items-center justify-between bg-white dark:bg-[#0c0c0e] border-b border-gray-100 dark:border-gray-800 shrink-0">
          <div className="flex items-center gap-3">
            <button onClick={onBack} className="p-1.5 hover:bg-orange-50 dark:hover:bg-orange-950/20 rounded-lg transition-all group">
              <ArrowLeft size={20} className="text-gray-500 group-hover:text-orange-600" />
            </button>
            <div className="flex items-center gap-2.5">
              <AssistantLogo size={32} />
              <div>
                <h1 className="text-[15px] font-extrabold text-[#f97316] leading-tight">Trip Planner</h1>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wide">Create your {city} itinerary</p>
              </div>
            </div>
          </div>
          <button onClick={() => {}} className="p-2 text-gray-400 hover:text-orange-600 transition-all">
            <Download size={18} />
          </button>
        </header>

        <div className="flex-1 overflow-hidden flex flex-col bg-[#F9F9F9] dark:bg-[#0a0a0c]">
          <ChatWindow 
            messages={messages} 
            onSuggestionClick={onSendMessage} 
            onSpeak={onSpeak}
            speakingMessageId={speakingMessageId}
            isTTSLoading={isTTSLoading}
            isLoading={isLoading} 
          />
          <div className="p-3 border-t border-gray-200 dark:border-gray-800 bg-white/50 dark:bg-black/20 backdrop-blur-md">
            <InputBar 
              onSendMessage={onSendMessage} 
              onStartLive={() => {}} 
              onOpenImageGen={() => {}} 
              isLoading={isLoading} 
            />
          </div>
        </div>
      </div>

      {/* Right Itinerary Column */}
      <div className="flex-1 flex flex-col bg-white dark:bg-[#08080a] overflow-y-auto custom-scrollbar relative">
        <div className="p-8 md:p-12 lg:p-16 max-w-4xl mx-auto w-full z-10">
          {parsedPlan ? (
            <div className="animate-in fade-in slide-in-from-right-10 duration-700">
              <div className="mb-10">
                <h2 className="text-[36px] md:text-[44px] font-black text-[#853517] dark:text-orange-200 mb-4 leading-[1.1] tracking-tight">
                  {parsedPlan.title}
                </h2>
                <p className="text-[#5f6368] dark:text-gray-400 text-[16px] md:text-[18px] leading-relaxed font-medium">
                  {parsedPlan.summary || `Experience the best of ${city} in a single, action-packed day! This itinerary covers the city's spiritual heart, its royal past, bustling markets, and delicious local cuisine.`}
                </p>
              </div>

              <div className="space-y-12">
                {parsedPlan.days.map((day) => (
                  <div key={day.dayNumber}>
                    <div className="flex items-center gap-3 mb-8 border-b border-orange-100 dark:border-orange-900/30 pb-4">
                      <h3 className="text-[22px] md:text-[26px] font-black text-[#f97316] dark:text-orange-500 tracking-tight">
                        Day {day.dayNumber}: {day.dayTitle}
                      </h3>
                    </div>

                    <div className="grid grid-cols-1 gap-8">
                      {day.activities.map((activity, aIdx) => (
                        <div key={aIdx} className="bg-white dark:bg-[#111] p-6 md:p-8 rounded-[2rem] border border-gray-100 dark:border-gray-800 shadow-sm transition-all hover:shadow-md relative overflow-hidden">
                          <div className="flex items-start gap-6">
                            <div className="w-14 h-14 bg-[#fff7ed] dark:bg-orange-950/30 rounded-[1.2rem] flex items-center justify-center text-3xl shrink-0 shadow-inner">
                              {getActivityIcon(activity.type)}
                            </div>
                            <div className="flex-1">
                              <div className="flex items-center gap-2 text-[#5f6368] dark:text-gray-400 text-[13px] font-bold mb-1">
                                {activity.timeRange}
                              </div>
                              <h4 className="text-[20px] md:text-[24px] font-black text-[#202124] dark:text-slate-100 mb-3 leading-tight">
                                {activity.title}
                              </h4>
                              <p className="text-[#5f6368] dark:text-slate-400 text-[15px] md:text-[16px] leading-relaxed font-medium mb-8">
                                {activity.description}
                              </p>

                              <div className="flex justify-center border-t border-gray-50 dark:border-gray-800/50 pt-6">
                                <a 
                                  href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(activity.title + ' ' + city)}`}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  className="inline-flex items-center gap-2.5 text-[#f97316] dark:text-orange-400 font-bold text-[14px] hover:opacity-80 transition-all px-6"
                                >
                                  <MapPin size={18} className="text-[#f97316]" />
                                  Get Directions
                                </a>
                              </div>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div className="h-full min-h-[600px] flex flex-col items-center justify-center text-center p-8 animate-in fade-in duration-1000 bg-[#fffaf5] dark:bg-[#0c0600]">
              <div className="w-52 h-52 bg-[#fff7ed] dark:bg-orange-950/20 rounded-[48px] flex items-center justify-center mb-12 relative shadow-inner">
                <div className="absolute inset-0 bg-[#fff7ed] dark:bg-orange-950/20 rounded-[48px] blur-sm -z-10" />
                <Briefcase size={96} className="text-[#fcd34d] opacity-60" strokeWidth={1.2} />
              </div>

              <h3 className="text-[38px] md:text-[48px] font-black text-[#bdc1c6] dark:text-gray-700 mb-6 tracking-tight leading-tight">
                Crafting Your City Experience
              </h3>

              <p className="text-[#9aa0a6] dark:text-gray-500 text-[18px] md:text-[20px] max-w-sm font-medium leading-relaxed mb-16">
                As you chat with the AI, your structured itinerary will materialize here in real-time.
              </p>

              <div className="px-10 py-4 bg-white dark:bg-[#111] rounded-full border border-gray-100 dark:border-gray-800 shadow-sm flex items-center gap-4">
                <div className="w-5 h-5 border-2 border-orange-200 border-t-[#f97316] rounded-full animate-spin" />
                <span className="text-[13px] font-black text-[#bdc1c6] uppercase tracking-[0.25em]">Waiting for input...</span>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

