      // Extract Title (usually the first bold or plain large text line)
      if (!titleFound && !trimmed.startsWith('-') && !trimmed.startsWith('*') && !trimmed.match(/Day\s*\d+/i)) {
        plan.title = trimmed.replace(/\*\*/g, '');
        titleFound = true;
        return;
      }

      // Detect Day headers
      const dayMatch = trimmed.match(/Day\s*(\d+)[:\s]*(.*)/i);
      if (dayMatch) {
        currentDay = {
          dayNumber: parseInt(dayMatch[1]),
          dayTitle: dayMatch[2].replace(/\*\*/g, '').trim() || 'City Exploration',
          activities: []
        };
        plan.days.push(currentDay);
        return;
      }

      // Summary: Content before the first day starts but after the title
      if (titleFound && plan.days.length === 0 && !trimmed.startsWith('-') && !trimmed.startsWith('*')) {
        plan.summary += (plan.summary ? ' ' : '') + trimmed.replace(/\*\*/g, '');
        return;
      }

      // Detect Activities within a day
      const activityMatch = trimmed.match(/^[-*✦]\s*(.*?[:\s-].*?)\s*[:]\s*(.*)/i);
      if (activityMatch && currentDay) {
        const timeAndTitle = activityMatch[1].replace(/\*\*/g, '').trim();
        const description = activityMatch[2].replace(/\*\*/g, '').trim();

        let type: PlanActivity['type'] = 'general';
        const lowerTitle = timeAndTitle.toLowerCase();
        if (lowerTitle.includes('temple')) type = 'temple';
        else if (lowerTitle.includes('food') || lowerTitle.includes('idli') || lowerTitle.includes('lunch') || lowerTitle.includes('dinner')) type = 'food';
        else if (lowerTitle.includes('shop')) type = 'shopping';

        currentDay.activities.push({
          timeRange: timeAndTitle.split(' ').slice(0, 2).join(' ') || 'Scheduled',
          title: timeAndTitle.includes('-') ? timeAndTitle.split('-')[1]?.trim() : timeAndTitle,
          description,
          type
        });
      }
    });

    return (plan.title || plan.summary || plan.days.length > 0) ? plan : null;
  }, [latestAssistantMsg, city]);

  const getActivityIcon = (type: PlanActivity['type']) => {
    switch(type) {
      case 'temple': return '🛕';
      case 'food': return '🍜';
      case 'shopping': return '🛍️';
      default: return '📍';
    }
  };

  // Determine if we should show the "Waiting for Input" screen
  // Show it ONLY if there's no assistant message and we're not currently loading a response
  const showWaitingState = !latestAssistantMsg && !isLoading;

  return (
    <div className="flex-1 flex flex-col md:flex-row bg-[#FAFAFA] dark:bg-[#0c0c0e] animate-in fade-in duration-300 overflow-hidden relative">
      {/* Left Chat Column */}
