import React, { useState, useEffect, useMemo } from 'react';
import { 
  ArrowLeft, 
  Download, 
  MapPin, 
  Briefcase, 
  Clock, 
  Navigation,
  Compass,
  Loader2
} from 'lucide-react';
import { Message } from '../types';
import InputBar from './InputBar';
import ChatWindow, { AssistantLogo } from './ChatWindow';

interface TripPlannerViewProps {
  messages: Message[];
  onSendMessage: (text: string) => void;
  onSpeak: (text: string, id: string) => void;
  speakingMessageId: string | null;
  isTTSLoading?: string | null;
  onBack: () => void;
  city: string;
  isLoading: boolean;
}

interface PlanActivity {
  timeRange: string;
  title: string;
  description: string;
  type: 'temple' | 'food' | 'shopping' | 'general';
}

interface PlanDay {
  dayNumber: number;
  dayTitle: string;
  activities: PlanActivity[];
}

const TripPlannerView: React.FC<TripPlannerViewProps> = ({ 
  messages, 
  onSendMessage, 
  onSpeak,
  speakingMessageId,
  isTTSLoading,
  onBack, 
  city, 
  isLoading 
}) => {
  // Parsing logic optimized for streaming
  const latestAssistantMsg = useMemo(() => {
    return [...messages].reverse().find(m => m.role === 'assistant' && m.content);
  }, [messages]);

  const parsedPlan = useMemo(() => {
    if (!latestAssistantMsg) return null;

    const content = latestAssistantMsg.content;
    const plan: { title: string, summary: string, days: PlanDay[] } = {
      title: '',
      summary: '',
      days: []
    };

    const lines = content.split('\n');
    let currentDay: PlanDay | null = null;
    let titleFound = false;

    lines.forEach(line => {
      const trimmed = line.trim();
      if (!trimmed) return;

      // Extract Title (Usually first significant line)
      if (!titleFound && !trimmed.startsWith('-') && !trimmed.startsWith('*') && !trimmed.match(/Day\s*\d+/i)) {
        plan.title = trimmed.replace(/\*\*/g, '');
        titleFound = true;
        return;
      }

      // Detect Day headers (e.g., "Day 1: ...")
      const dayMatch = trimmed.match(/Day\s*(\d+)[:\s]*(.*)/i);
      if (dayMatch) {
        currentDay = {
          dayNumber: parseInt(dayMatch[1]),
          dayTitle: dayMatch[2].replace(/\*\*/g, '').trim() || 'City Exploration',
          activities: []
        };
        plan.days.push(currentDay);
        return;
      }

      // Summary lines (between title and first day)
      if (titleFound && plan.days.length === 0 && !trimmed.startsWith('-') && !trimmed.startsWith('*')) {
        plan.summary += (plan.summary ? ' ' : '') + trimmed.replace(/\*\*/g, '');
        return;
      }

      // Detect Activities (e.g., "- 8:00 AM: Meenakshi temple...")
      const activityMatch = trimmed.match(/^[-*✦]\s*(.*?[:\s-].*?)\s*[:]\s*(.*)/i);
      if (activityMatch && currentDay) {
        const timeAndTitlePart = activityMatch[1].replace(/\*\*/g, '').trim();
        const description = activityMatch[2].replace(/\*\*/g, '').trim();

        let type: PlanActivity['type'] = 'general';
        const lowerTitle = timeAndTitlePart.toLowerCase();
        if (lowerTitle.includes('temple')) type = 'temple';
        else if (lowerTitle.includes('food') || lowerTitle.includes('idli') || lowerTitle.includes('lunch') || lowerTitle.includes('dinner')) type = 'food';
        else if (lowerTitle.includes('shop')) type = 'shopping';

        // Split "8:00 AM - Temple" into time and title
        const parts = timeAndTitlePart.split(/[:\-]/);
        const timeRange = parts[0]?.trim() || 'Scheduled';
        const title = parts.length > 1 ? parts.slice(1).join('-').trim() : timeAndTitlePart;

        currentDay.activities.push({
          timeRange,
          title,
          description,
          type
        });
      }
    });

    return (plan.title || plan.summary || plan.days.length > 0) ? plan : null;
  }, [latestAssistantMsg, city]);

  const getActivityIcon = (type: PlanActivity['type']) => {
    switch(type) {
      case 'temple': return '🛕';
      case 'food': return '🍜';
      case 'shopping': return '🛍️';
      default: return '📍';
    }
  };

  const isGenerating = isLoading || (latestAssistantMsg && !parsedPlan);

  return (
    <div className="flex-1 flex flex-col md:flex-row bg-[#FAFAFA] dark:bg-[#0c0c0e] animate-in fade-in duration-500 overflow-hidden relative">
      {/* Left Chat Column */}
      <div className="w-full md:w-[450px] flex flex-col border-r border-gray-200 dark:border-gray-800 relative z-10 bg-[#fefefe] dark:bg-[#0c0c0e] shadow-xl shrink-0">
        <header className="px-5 py-4 flex items-center justify-between bg-white dark:bg-[#0c0c0e] border-b border-gray-100 dark:border-gray-800 shrink-0">
          <div className="flex items-center gap-3">
            <button onClick={onBack} className="p-1.5 hover:bg-orange-50 dark:hover:bg-orange-950/20 rounded-lg transition-all group">
              <ArrowLeft size={20} className="text-gray-500 group-hover:text-orange-600" />
            </button>
            <div className="flex items-center gap-2.5">
              <AssistantLogo size={32} />
              <div>
                <h1 className="text-[15px] font-extrabold text-[#f97316] leading-tight">Trip Planner</h1>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wide">Create your {city} itinerary</p>
              </div>
            </div>
          </div>
          <button onClick={() => {}} className="p-2 text-gray-400 hover:text-orange-600 transition-all">
            <Download size={18} />
          </button>
        </header>

        <div className="flex-1 overflow-hidden flex flex-col bg-[#F9F9F9] dark:bg-[#0a0a0c]">
          <ChatWindow 
            messages={messages} 
            onSuggestionClick={onSendMessage} 
            onSpeak={onSpeak}
            speakingMessageId={speakingMessageId}
            isTTSLoading={isTTSLoading}
            isLoading={isLoading} 
          />
          <div className="p-4 border-t border-gray-200 dark:border-gray-800 bg-white/50 dark:bg-black/20 backdrop-blur-md">
            <InputBar 
              onSendMessage={onSendMessage} 
              onStartLive={() => {}} 
              onOpenImageGen={() => {}} 
              isLoading={isLoading} 
            />
          </div>
        </div>
      </div>

      {/* Right Itinerary Column - THE "BOX" */}
      <div className="flex-1 flex flex-col bg-white dark:bg-[#08080a] overflow-y-auto custom-scrollbar relative">
        <div className="p-8 md:p-14 lg:p-20 max-w-4xl mx-auto w-full z-10">
          {parsedPlan ? (
            <div className="animate-in fade-in duration-500">
              {parsedPlan.title && (
                <div className="mb-12">
                  <h2 className="text-[42px] md:text-[52px] font-black text-[#853517] dark:text-orange-200 mb-5 leading-[1.05] tracking-tight">
                    {parsedPlan.title}
                  </h2>
                  <p className="text-[#5f6368] dark:text-gray-400 text-[17px] md:text-[19px] leading-relaxed font-medium">
                    {parsedPlan.summary || `Experience the best of ${city} with this curated plan.`}
                  </p>
                </div>
              )}

              <div className="space-y-16">
                {parsedPlan.days.map((day) => (
                  <div key={day.dayNumber} className="animate-in slide-in-from-bottom-6 duration-700">
                    <div className="flex items-center gap-4 mb-10 border-b border-orange-100 dark:border-orange-900/30 pb-5">
                      <h3 className="text-[24px] md:text-[30px] font-black text-[#f97316] dark:text-orange-500 tracking-tight">
                        Day {day.dayNumber}: {day.dayTitle}
                      </h3>
                    </div>

                    <div className="grid grid-cols-1 gap-10">
                      {day.activities.map((activity, aIdx) => (
                        <div key={aIdx} className="bg-white dark:bg-[#111] p-8 md:p-10 rounded-[2.5rem] border border-gray-100 dark:border-gray-800 shadow-sm transition-all hover:shadow-xl relative overflow-hidden group">
                          <div className="flex items-start gap-7">
                            <div className="w-16 h-16 bg-[#fff7ed] dark:bg-orange-950/30 rounded-[1.5rem] flex items-center justify-center text-4xl shrink-0 shadow-inner group-hover:scale-105 transition-transform">
                              {getActivityIcon(activity.type)}
                            </div>
                            <div className="flex-1">
                              <div className="flex items-center gap-2 text-[#5f6368] dark:text-gray-400 text-[14px] font-bold mb-1.5 uppercase tracking-wide">
                                {activity.timeRange}
                              </div>
                              <h4 className="text-[22px] md:text-[26px] font-black text-[#202124] dark:text-slate-100 mb-3.5 leading-tight">
                                {activity.title}
                              </h4>
                              <p className="text-[#5f6368] dark:text-slate-400 text-[16px] md:text-[17px] leading-relaxed font-medium mb-10">
                                {activity.description}
                              </p>

                              <div className="flex items-center justify-center border-t border-gray-50 dark:border-gray-800/50 pt-8">
                                <div className="h-6 w-[1px] bg-gray-200 dark:bg-gray-800 mx-10 hidden md:block" />
                                <a 
                                  href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(activity.title + ' ' + city)}`}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  className="inline-flex items-center gap-3 text-[#f97316] dark:text-orange-400 font-extrabold text-[15px] hover:opacity-80 transition-all px-6 py-2 group/link"
                                >
                                  <MapPin size={20} className="text-[#f97316] group-hover/link:bounce" />
                                  Get Directions
                                </a>
                                <div className="h-6 w-[1px] bg-gray-200 dark:bg-gray-800 mx-10 hidden md:block" />
                              </div>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>

              {isLoading && (
                <div className="mt-16 flex items-center justify-center gap-4 text-orange-500 font-black tracking-widest uppercase text-sm animate-pulse">
                   <Loader2 size={24} className="animate-spin" />
                   <span>Expanding your itinerary...</span>
                </div>
              )}
            </div>
          ) : (
            /* EXACT MATCH FOR IMAGE 1: WAITING STATE */
            <div className="h-full min-h-[600px] flex flex-col items-center justify-center text-center p-8 animate-in fade-in duration-1000">
              <div className="w-56 h-56 bg-[#fffaf5] dark:bg-orange-950/10 rounded-[56px] flex items-center justify-center mb-14 relative shadow-inner">
                <Briefcase size={100} className="text-[#fcd34d] opacity-50" strokeWidth={1.2} />
              </div>

              <h3 className="text-[42px] md:text-[52px] font-black text-[#bdc1c6] dark:text-gray-800 mb-6 tracking-tight leading-tight">
                Crafting Your City Experience
              </h3>

              <p className="text-[#9aa0a6] dark:text-gray-600 text-[19px] md:text-[21px] max-w-md font-medium leading-relaxed mb-16 px-4">
                As you chat with the AI, your structured itinerary will materialize here in real-time.
              </p>

              <div className="px-12 py-5 bg-white dark:bg-[#111] rounded-full border border-gray-100 dark:border-gray-800 shadow-sm flex items-center gap-5 scale-110">
                <div className="w-5 h-5 border-2 border-orange-200 border-t-[#f97316] rounded-full animate-spin" />
                <span className="text-[14px] font-black text-[#bdc1c6] uppercase tracking-[0.25em]">WAITING FOR INPUT...</span>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default TripPlannerView;
